const items = [{"id": 1, "topic": 0, "q": "Identificați compoziția nucleului atomic.", "a": "Nucleul este format din nucleoni: protoni (sarcină pozitivă) și neutroni (fără sarcină).", "e": "Nucleul are sarcină +, iar electronii (–) se rotesc în jurul lui.", "o": ["Protoni, neutroni și electroni orbitali", "Protoni și electroni, cu neutronii în înveliș", "Numai protoni, indiferent de izotop"], "ref": "Lucrări practice, p. 152"}, {"id": 2, "topic": 0, "q": "Determinați condiția în care atomul este neutru din punct de vedere electric.", "a": "Atomul este neutru când numărul electronilor din jurul nucleului = numărul protonilor din nucleu.", "e": "Sarcinile + ale protonilor sunt compensate exact de sarcinile – ale electronilor.", "o": ["Numărul electronilor este egal cu numărul neutronilor", "Numărul protonilor este egal cu suma neutronilor și electronilor", "Numărul protonilor este egal cu numărul neutronilor, indiferent de electroni"], "ref": "Lucrări practice, p. 152"}, {"id": 3, "topic": 0, "q": "Precizați starea atomului în care electronii se rotesc pe orbite fără să emită sau să absoarbă energie.", "a": "Starea staționară (primul postulat al lui Bohr).", "e": "În modelul lui Bohr, un electron aflat într-o stare staționară permisă nu emite și nu absoarbe energie. Schimbul de energie are loc la tranziția între niveluri.", "o": ["Doar în starea fundamentală, fiindcă orice stare excitată radiază continuu", "În timpul oricărei tranziții între niveluri permise", "Pe orice orbită clasică, dacă viteza electronului este constantă"], "ref": "Lucrări practice, p. 152"}, {"id": 4, "topic": 0, "q": "Identificați fenomenul care are loc atunci când un atom absoarbe energie din exterior.", "a": "Excitarea atomului: electronii trec pe nivele mai îndepărtate de nucleu.", "e": "Energia primită „ridică” electronul pe un nivel superior (Fig. 19.1 a).", "o": ["Distribuția radiației emise de o sursă în funcție de frecvență sau lungime de undă", "Identificarea componentelor unei probe prin liniile spectrale caracteristice", "Tranziții între niveluri energetice discrete, specifice speciei atomice"], "ref": "Lucrări practice, p. 152"}, {"id": 5, "topic": 0, "q": "Determinați ce reprezintă mărimea h în relația E = hc/λ.", "a": "h este constanta lui Planck.", "e": "E = hν = hc/λ; h = 6,62·10⁻³⁴ J·s.", "o": ["Constanta lui Boltzmann, măsurată în J/K", "Constanta lui Planck redusă ℏ, fără factorul 2π", "Viteza luminii, măsurată în m/s"], "ref": "Lucrări practice, p. 152"}, {"id": 6, "topic": 0, "q": "Precizați cauza apariției liniilor spectrale proprii fiecărui atom.", "a": "Configurația electronică a atomului căruia îi aparțin.", "e": "Fiecare atom are alte nivele energetice, deci alte lungimi de undă emise/absorbite – linii proprii numai lui.", "o": ["Diferențele de temperatură scindează în mod identic spectrul tuturor atomilor", "Poziția liniilor este determinată exclusiv de concentrația atomilor", "Electronii pot avea orice energie, dar prisma selectează frecvențe discrete"], "ref": "Lucrări practice, p. 153"}, {"id": 7, "topic": 0, "q": "Definiți analiza spectrală calitativă.", "a": "Metoda fizică de determinare a compoziției chimice a substanțelor cu ajutorul spectrelor (după liniile spectrale).", "e": "Fiecare element are liniile lui, deci îl recunoști ca pe o „amprentă”.", "o": ["Estimarea concentrației folosind numai intensitatea totală, fără identificarea liniilor", "Măsurarea grosimii probei din unghiul de refracție", "Determinarea masei sursei din lățimea fasciculului"], "ref": "Lucrări practice, p. 153"}, {"id": 8, "topic": 0, "q": "Definiți spectrul de emisie.", "a": "Totalitatea radiațiilor de diferite λ pe care un atom (sau moleculă) le poate emite când primește energie din exterior.", "e": "Studiul lor = spectroscopie de emisie.", "o": ["Identificarea componentelor unei probe prin liniile spectrale caracteristice", "Distribuția absorbției radiației incidente în funcție de lungimea de undă", "O specie absoarbe la lungimile de undă la care poate emite pentru aceleași tranziții"], "ref": "Lucrări practice, p. 153"}, {"id": 9, "topic": 0, "q": "Definiți spectrul de absorbție.", "a": "Totalitatea radiațiilor de diferite λ absorbite de un atom (moleculă) când este examinat într-un spectru continuu.", "e": "Studiul lor = spectroscopie de absorbție.", "o": ["Linii luminoase colorate pe fond întunecat pentru un gaz atomic rarefiat", "Identificarea componentelor unei probe prin liniile spectrale caracteristice", "Tranziții între niveluri energetice discrete, specifice speciei atomice"], "ref": "Lucrări practice, p. 153"}, {"id": 10, "topic": 0, "q": "Identificați aspectul vizual al unui spectru de emisie în domeniul vizibil.", "a": "Linii luminoase (de diferite culori) pe fond întunecat.", "e": "Atomul emite doar anumite λ – apar doar acele linii colorate.", "o": ["Distribuția absorbției radiației incidente în funcție de lungimea de undă", "Tranziții între niveluri energetice discrete, specifice speciei atomice", "Identificarea componentelor unei probe prin liniile spectrale caracteristice"], "ref": "Lucrări practice, p. 153"}, {"id": 11, "topic": 0, "q": "Identificați aspectul vizual al unui spectru de absorbție.", "a": "Linii sau benzi întunecate pe fondul unui spectru continuu.", "e": "Substanța „scoate” din lumina albă exact λ pe care le absoarbe.", "o": ["Separarea spectrală prin prismă optică sau rețea de difracție", "Linii luminoase colorate pe fond întunecat pentru un gaz atomic rarefiat", "Distribuția absorbției radiației incidente în funcție de lungimea de undă"], "ref": "Lucrări practice, p. 154"}, {"id": 12, "topic": 0, "q": "Selectați afirmația care corespunde legii lui Kirchhoff (legea inversiunii liniilor spectrale).", "a": "„Substanța absoarbe radiații cu acele lungimi de undă pe care este în stare să le emită.”", "e": "Între spectrul de emisie și cel de absorbție (în condiții identice) există corespondență directă.", "o": ["O specie absoarbe exclusiv la lungimi de undă mai mari decât cele emise", "Coincidența liniilor depinde de egalitatea intensităților de emisie și absorbție", "În aceleași condiții, absorbția este maximă între liniile de emisie"], "ref": "Lucrări practice, p. 154"}, {"id": 13, "topic": 0, "q": "Precizați caracteristica unei surse de lumină monocromatică.", "a": "Emite o singură lungime de undă (ex. laserul).", "e": "Mai multe λ → sursă policromă.", "o": ["O specie absoarbe la lungimile de undă la care poate emite pentru aceleași tranziții", "Dependența indicelui de refracție și implicit a vitezei de fază de lungimea de undă", "Linii luminoase colorate pe fond întunecat pentru un gaz atomic rarefiat"], "ref": "Lucrări practice, p. 155"}, {"id": 14, "topic": 0, "q": "Identificați aparatul utilizat pentru înregistrarea spectrului pe o placă fotografică.", "a": "Spectrograful.", "e": "Spectroscopul – spectrul se privește cu ochiul; spectrograful – se înregistrează pe placă fotografică sau inscriptor.", "o": ["Cuarț", "Lampă de cuarț cu vapori de mercur", "Sare gemă, adică clorură de sodiu cristalină"], "ref": "Lucrări practice, p. 155"}, {"id": 15, "topic": 0, "q": "Precizați baza de funcționare a spectroscopului.", "a": "Prisma optică sau rețeaua de difracție.", "e": "Ele descompun lumina în componente de diferite λ.", "o": ["Linii întunecate suprapuse unui spectru continuu luminos", "Emite predominant o singură lungime de undă, cu bandă spectrală foarte îngustă", "Dependența indicelui de refracție și implicit a vitezei de fază de lungimea de undă"], "ref": "Lucrări practice, p. 155"}, {"id": 16, "topic": 0, "q": "Definiți fenomenul de dispersie a luminii.", "a": "Dependența indicelui de refracție de frecvența (lungimea de undă) luminii – descoperită de Newton.", "e": "Din cauza ei lumina albă se descompune în culori în prismă.", "o": ["O specie absoarbe la lungimile de undă la care poate emite pentru aceleași tranziții", "Emite predominant o singură lungime de undă, cu bandă spectrală foarte îngustă", "Separarea spectrală prin prismă optică sau rețea de difracție"], "ref": "Lucrări practice, p. 155"}, {"id": 17, "topic": 0, "q": "Determinați limitele aproximative ale lungimilor de undă pentru spectrul vizibil.", "a": "Aproximativ 400 nm – 760 nm.", "e": "Violet ≈ 400 nm, roșu ≈ 760 nm.", "o": ["200–400 nm", "760–1 400 nm", "400–1 400 nm"], "ref": "Lucrări practice, p. 155"}, {"id": 18, "topic": 0, "q": "Identificați modificarea vitezei de propagare a luminii și a indicelui de refracție la trecerea de la culoarea roșie spre cea violetă (la micșorarea lungimii de undă).", "a": "Viteza se micșorează, iar indicele de refracție se mărește.", "e": "Violetul e mai încetinit și mai deviat decât roșul.", "o": ["Viteza crește, iar indicele scade", "Viteza și indicele cresc simultan", "Viteza rămâne constantă în sticlă, iar indicele crește"], "ref": "Lucrări practice, p. 156"}, {"id": 19, "topic": 0, "q": "Determinați modificarea unghiului de deviație D din relația D = (n - 1)A atunci când unghiul prismei A se dublează, indicii de refracție rămânând constanți.", "a": "D se dublează.", "e": "D = (n – 1)A este direct proporțional cu A.", "o": ["D se înjumătățește", "D rămâne constant", "D crește de patru ori"], "ref": "Lucrări practice, p. 156, 161"}, {"id": 20, "topic": 0, "q": "Identificați proprietatea rețelei de difracție în raport cu deviația razelor.", "a": "Rețeaua de difracție realizează o deviație proporțională cu lungimea de undă.", "e": "Spre deosebire de prismă (unde deviația depinde de n).", "o": ["Unghiul de difracție scade cu λ la același ordin nenul", "În toate ordinele unghiul rămâne fix când λ se modifică", "Unghiul depinde de puterea fasciculului, iar d determină doar intensitatea maximelor"], "ref": "Lucrări practice, p. 156"}, {"id": 21, "topic": 0, "q": "Precizați rolul colimatorului în structura spectroscopului.", "a": "Trimite pe fața de incidență a prismei un fascicul îngust de raze paralele.", "e": "E format din lentilă convergentă L1 și fantă reglabilă F în focarul lentilei.", "o": ["Stabilirea relației dintre diviziunile scării și lungimile de undă cunoscute", "Pe abscisă diviziunile scării, pe ordonată lungimile de undă", "Sare gemă, adică clorură de sodiu cristalină"], "ref": "Lucrări practice, p. 157"}, {"id": 22, "topic": 0, "q": "Identificați materialul utilizat pentru prisma optică la cercetarea spectrului în domeniul ultraviolet.", "a": "Cuarțul.", "e": "Sticlă obișnuită – vizibil; cuarț – UV; sare gemă – IR.", "o": ["Clorură de sodiu cristalină", "Sticlă optică obișnuită", "Sticlă cu plumb pentru vizibil"], "ref": "Lucrări practice, p. 156"}, {"id": 23, "topic": 0, "q": "Identificați materialul utilizat pentru prisma optică la cercetarea spectrului în domeniul infraroșu.", "a": "Sarea gemă.", "e": "IR → sare gemă.", "o": ["Cuarț folosit la spectroscopia UV", "Sticlă optică obișnuită", "Sticlă cu plumb folosită la dispersia vizibilului"], "ref": "Lucrări practice, p. 156"}, {"id": 24, "topic": 0, "q": "Definiți procesul de etalonare a spectroscopului.", "a": "Stabilirea unei dependențe între diviziunile scării gradate și lungimile de undă ale radiațiilor.", "e": "Se folosesc surse cu λ cunoscute, distribuite în tot vizibilul.", "o": ["Transformă lumina de la fanta aflată în focar într-un fascicul aproape paralel", "Pe abscisă diviziunile scării, pe ordonată lungimile de undă", "Sare gemă, adică clorură de sodiu cristalină"], "ref": "Lucrări practice, p. 157–158"}, {"id": 25, "topic": 0, "q": "Selectați sursa de lumină etalon frecvent utilizată pentru calibrarea spectroscopului", "a": "Lampa de cuarț cu vapori de mercur (etalon mercur).", "e": "Liniile ei: 408, 436, 546, 577, 579, 623, 691 nm (Tabelul 19.1).", "o": ["Lampă cu filament incandescent fără linii de referință", "LED alb folosit drept sursă continuă", "Laser He–Ne cu o singură linie vizibilă"], "ref": "Lucrări practice, p. 157–158"}, {"id": 26, "topic": 0, "q": "Precizați mărimile care se plasează pe axele sistemului de coordonate la construirea curbei de etalonare.", "a": "Abscisă (Ox) – diviziunile scării gradate n°; ordonată (Oy) – lungimile de undă λ.", "e": "Unind punctele se obține curba de etalonare.", "o": ["Pe abscisă lungimile de undă, iar pe ordonată diviziunile scării", "Pe abscisă timpul de expunere, iar pe ordonată intensitatea", "Pe abscisă concentrația și pe ordonată absorbanța"], "ref": "Lucrări practice, p. 157–158"}, {"id": 27, "topic": 0, "q": "Precizați aplicația medicală a analizei spectrale calitative referitoare la sânge.", "a": "Identificarea urmelor de sânge (și stabilirea cauzelor intoxicațiilor).", "e": "Hemoglobina și derivații săi au spectre de absorbție caracteristice.", "o": ["Identificarea hemoglobinei doar din viteza de sedimentare a eritrocitelor", "Determinarea numărului leucocitelor prin liniile de sodiu", "Dozarea ionilor alcalini folosind exclusiv pozițiile benzilor hemoglobinei"], "ref": "Lucrări practice, p. 159"}, {"id": 28, "topic": 0, "q": "Identificați metoda spectrală utilizată pentru dozarea ionilor alcalini din produsele biologice.", "a": "Metoda flamfotometrică (variantă a analizei spectrale cantitative de emisie).", "e": "Dozează ionii alcalini (ex. Na, K) din produsele biologice.", "o": ["Polarimetria, prin rotația planului luminii în soluție", "Spectroscopia moleculară a derivaților hemoglobinei", "Fotocolorimetria fără reactiv, bazată pe culoarea proprie a ionilor de sodiu și potasiu în apă"], "ref": "Lucrări practice, p. 159"}, {"id": 29, "topic": 0, "q": "Identificați particulele care intră în alcătuirea atomului și a nucleului său.", "a": "Atomul: nucleu + electroni; nucleul: protoni și neutroni (nucleoni).", "e": "Protoni +, neutroni neutri, electroni –.", "o": ["Fotometria de flacără, prin emisie atomică", "Identificarea formelor de hemoglobină după spectrele de absorbție", "Surse monocromatice și surse policromatice"], "ref": "Lucrări practice, p. 152–153"}, {"id": 30, "topic": 0, "q": "selectați afirmațiile care corespund postulatelor lui Bohr.", "a": "1) Electronii se rotesc pe orbite bine determinate fără să emită/absoarbă energie (stări staționare). 2) Atomul emite sau absoarbe radiație doar la trecerea dintr-o stare staționară în alta; energia = diferența energiilor celor două nivele.", "e": "Fiecare stare staționară corespunde unei stări energetice a atomului.", "o": ["Absorbția rezonantă mărește energia atomului și poate promova electronul pe un nivel superior", "Tranziția la un nivel inferior scade energia atomului și poate produce un foton hν = Eᵢ − E𝒇", "Atomul trece pe nivelul superior, absorbind fotonul rezonant"], "ref": "Lucrări practice, p. 152–153"}, {"id": 31, "topic": 0, "q": "Precizați consecințele absorbției de energie radiantă de către un atom.", "a": "Electronii trec pe nivele mai îndepărtate de nucleu – atomul se excită.", "e": "Energia absorbită = Es – Ei.", "o": ["Tranziția la un nivel inferior scade energia atomului și poate produce un foton hν = Eᵢ − E𝒇", "Stări staționare permise fără emisie și tranziții cu hν = ΔE în modul", "Fotonul nou are aceeași frecvență, fază, direcție și polarizare în modul stimulat"], "ref": "Lucrări practice, p. 152–153"}, {"id": 32, "topic": 0, "q": "Precizați consecințele emisiei de energie de către un atom.", "a": "Electronii trec pe nivele mai apropiate de nucleu (dezexcitare), emițând fotoni hν.", "e": "Energia fotonului = diferența dintre nivele.", "o": ["Absorbția rezonantă mărește energia atomului și poate promova electronul pe un nivel superior", "Stări staționare permise fără emisie și tranziții cu hν = ΔE în modul", "Fotonul nou are aceeași frecvență, fază, direcție și polarizare în modul stimulat"], "ref": "Lucrări practice, p. 152–153"}, {"id": 33, "topic": 0, "q": "Selectați caracteristicile liniilor spectrale.", "a": "Sunt radiații cu λ bine determinate, proprii numai atomului respectiv, cauzate de configurația lui electronică; se cunosc cu precizie pentru fiecare element.", "e": "De aceea permit identificarea elementelor dintr-un amestec.", "o": ["Poziția fiecărei linii depinde exclusiv de intensitatea iluminării", "Liniile tuturor elementelor coincid dacă se folosește aceeași prismă", "Intensitatea este aceeași pentru toate liniile unui element, la orice temperatură"], "ref": "Lucrări practice, p. 152–153"}, {"id": 34, "topic": 0, "q": "Identificați formele posibile ale spectrelor de emisie și de absorbție în funcție de compoziția chimică și starea fizică.", "a": "Spectre de linii, de benzi sau continue.", "e": "Forma depinde de compoziția chimică și starea fizică a substanței.", "o": ["Emisia este întotdeauna continuă, iar absorbția este întotdeauna de linii", "Atât emisia, cât și absorbția sunt obligatoriu monocromatice pentru o substanță pură", "Forma spectrului este stabilită doar de lățimea fantei, independent de starea probei"], "ref": "Lucrări practice, p. 153–154"}, {"id": 35, "topic": 0, "q": "Precizați proprietățile spectrului de emisie în domeniul vizibil.", "a": "Linii luminoase colorate pe fond întunecat; fiecare element are liniile lui (număr, culoare, λ).", "e": "Ex.: Na – linia galbenă D ≈ 589 nm.", "o": ["Absorbția selectivă produce minime de transmisie la lungimi de undă caracteristice", "Spectre continue, de linii sau de benzi, în funcție de sursă ori absorbant", "Identificarea speciilor și investigarea structurii prin tranzițiile lor spectrale"], "ref": "Lucrări practice, p. 153–154"}, {"id": 36, "topic": 0, "q": "Precizați proprietățile spectrului de absorbție.", "a": "Linii sau benzi întunecate pe fond de spectru continuu; liniile apar la aceleași λ pe care substanța le poate emite.", "e": "Legea lui Kirchhoff (inversiunea liniilor).", "o": ["Pentru un gaz atomic, liniile sunt luminoase și apar la lungimi de undă caracteristice", "Spectre continue, de linii sau de benzi, în funcție de sursă ori absorbant", "Refracție la fețele prismei și dispersie a componentelor luminii albe"], "ref": "Lucrări practice, p. 153–154"}, {"id": 37, "topic": 0, "q": "Selectați tipurile de surse de lumină în funcție de numărul lungimilor de undă emise.", "a": "Monocromatice (o singură λ) și policrome (mai multe λ).", "e": "Laserul – monocromatic; becul – policrom.", "o": ["Fotometria de flacără, prin emisie atomică", "Refracție la fețele prismei și dispersie a componentelor luminii albe", "Spectru continuu în domeniul vizibil"], "ref": "Lucrări practice, p. 155"}, {"id": 38, "topic": 0, "q": "Precizați fenomenele care au loc la trecerea luminii albe printr-o prismă din sticlă.", "a": "Refracția și dispersia luminii: fiecare rază e deviată cu alt unghi D → pe ecran apare spectrul (culorile de la roșu la violet).", "e": "Violetul se deviază cel mai mult, roșul cel mai puțin.", "o": ["Spectre continue, de linii sau de benzi, în funcție de sursă ori absorbant", "Absorbția selectivă produce minime de transmisie la lungimi de undă caracteristice", "Identificarea speciilor și investigarea structurii prin tranzițiile lor spectrale"], "ref": "Lucrări practice, p. 156"}, {"id": 39, "topic": 0, "q": "Determinați consecințele micșorării lungimii de undă (de la roșu spre violet) la propagarea luminii într-un mediu dispersiv.", "a": "Viteza luminii scade, indicele de refracție crește, deci deviația crește.", "e": "Violetul este cel mai deviat.", "o": ["D este deviația, n₂ indicele prismei, n₁ indicele mediului și A unghiul prismei", "Se poate emite un foton cu E = ΔE pozitiv și λ = hc/ΔE", "Deviația D se dublează, în limita aproximației pentru prismă subțire"], "ref": "Lucrări practice, p. 156"}, {"id": 40, "topic": 0, "q": "Analizați relația unghiului de deviație D = (n2 - n1)A și identificați mărimile din care este compusă.", "a": "D – unghiul de deviație; n₂ – indicele de refracție al materialului prismei; n₁ – indicele de refracție al mediului; A – unghiul prismei.", "e": "Relația e valabilă pentru unghiuri de incidență mici.", "o": ["La lungimi de undă mai mici cresc n și deviația prismatică, iar v scade", "Se poate emite un foton cu E = ΔE pozitiv și λ = hc/ΔE", "La ordin fix și incidență normală, unghiul de difracție crește cu lungimea de undă"], "ref": "Lucrări practice, p. 156"}, {"id": 41, "topic": 0, "q": "Identificați componentele de bază ale spectroscopului cu două tuburi.", "a": "Prisma optică P, colimatorul K (lentila L1 + fanta F) și luneta L (obiectiv L2 + ocular L3); plus scara gradată.", "e": "Luneta se poate roti în jurul unei axe verticale.", "o": ["Ocularul lunetei", "Lampă de cuarț cu vapori de mercur", "Sare gemă, adică clorură de sodiu cristalină"], "ref": "Lucrări practice, p. 156–157"}, {"id": 42, "topic": 0, "q": "Precizați importanța analizei spectrale în cercetarea medico-biologică structurală.", "a": "Studiul structurii chimice a diverselor molecule organice; aminoacizii și acizii nucleici prezintă benzi caracteristice.", "e": "Spectrul arată cum e construită molecula.", "o": ["Măsoară transmitanța ori absorbanța pentru analiza calitativă și dozarea analitului", "Identificarea derivaților hemoglobinei și a unor substanțe sau elemente din probe toxicologice", "Absorbția selectivă produce minime de transmisie la lungimi de undă caracteristice"], "ref": "Lucrări practice, p. 159"}, {"id": 43, "topic": 0, "q": "Identificați aplicațiile analizei spectrale calitative în diagnostic și toxicologie.", "a": "Identificarea urmelor de sânge și stabilirea cauzelor intoxicațiilor (toxicologie).", "e": "Se bazează pe spectrele de absorbție ale hemoglobinei și derivaților ei.", "o": ["Măsoară transmitanța ori absorbanța pentru analiza calitativă și dozarea analitului", "Identificarea speciilor și investigarea structurii prin tranzițiile lor spectrale", "Dispersia elementului optic, fanta îngustă și focalizarea corectă ajută separarea liniilor"], "ref": "Lucrări practice, p. 159"}, {"id": 44, "topic": 0, "q": "Precizați rolul spectrofotometrelor în laboratoarele clinice moderne.", "a": "Sunt de strictă necesitate pentru identificarea unor substanțe și constatarea rezultatelor reacțiilor de laborator.", "e": "Text.", "o": ["Identificarea speciilor și investigarea structurii prin tranzițiile lor spectrale", "Identificarea derivaților hemoglobinei și a unor substanțe sau elemente din probe toxicologice", "Dispersia elementului optic, fanta îngustă și focalizarea corectă ajută separarea liniilor"], "ref": "Lucrări practice, p. 159"}, {"id": 45, "topic": 0, "q": "Care tip de spectru este reprezentat în imagine?", "a": "Spectru continuu (de emisie) – toate culorile trec una în alta, fără linii.", "e": "Nu are nici linii luminoase separate, nici linii negre.", "o": ["Spectru de emisie cu linii luminoase izolate", "Spectru de absorbție cu linii întunecate pe fond continuu", "Spectru format doar din benzi moleculare separate de zone negre"], "image": "../fig-45.png", "ref": "Lucrări practice, p. 153"}, {"id": 46, "topic": 0, "q": "În imaginea alăturată elementul numărul 3 reprezintă:", "a": "3 – ocularul lunetei (locul prin care privește observatorul).", "e": "1 – colimator, 2 – luneta, 4 – prisma, 5 – sursa de lumină.", "o": ["Colimatorul", "Prisma optică", "Sursa de lumină"], "image": "../fig-46.png", "ref": "Lucrări practice, p. 156–157"}, {"id": 47, "topic": 0, "q": "În spectroscopul reprezentat, calitatea separării liniilor spectrale depinde de caracteristicile optice ale sistemului. Care dintre aceste caracteristici sunt corecte?", "a": "Corecte: prisma (4) produce dispersia (n depinde de λ; compoziția prismei trebuie să corespundă domeniului); colimatorul (1) trimite un fascicul îngust de raze paralele, iar fanta se reglează pentru finețea liniilor și luminozitate suficientă; ocularul se deplasează pentru imagine clară; sticla grea dă dispersie mai pronunțată.", "e": "Separarea liniilor e mai bună când diferența de indici pentru diferite λ e mare și fasciculul e îngust și paralel.", "o": ["Se lărgește fanta și se defocalizează obiectivul pentru a separa linii apropiate", "Se schimbă ocularul, iar dispersia prismei și lățimea fantei nu influențează rezoluția", "Se urmărește doar creșterea puterii sursei, chiar dacă liniile se suprapun"], "image": "../fig-47.png", "ref": "Lucrări practice, p. 156–157"}, {"id": 48, "topic": 0, "q": "Precizați aplicațiile medicale ale analizei spectrale prezentate în temă.", "a": "Studiul structurii moleculelor organice (aminoacizi, acizi nucleici); identificarea urmelor de sânge; stabilirea cauzelor intoxicațiilor; dozarea flamfotometrică a ionilor alcalini; spectrofotometrele în laboratoarele clinice.", "e": "Rezumatul „Importanța analizei spectrale”,.", "o": ["Dispersia elementului optic, fanta îngustă și focalizarea corectă ajută separarea liniilor", "Aceeași specie și aceeași pereche de niveluri pentru tranziții inverse, cu populații adecvate", "Identificarea derivaților hemoglobinei și a unor substanțe sau elemente din probe toxicologice"], "ref": "Lucrări practice, p. 159"}, {"id": 49, "topic": 0, "q": "În formula E = hc/λ, determinați modificările ce au loc când un electron efectuează o tranziție pe un nivel mai apropiat de nucleu.", "a": "Atomul emite un foton (se dezexcită), cu energia E = hc/λ egală cu diferența dintre nivele.", "e": "Cu cât saltul energetic e mai mare, cu atât λ e mai mică.", "o": ["Se absoarbe un foton cu energie egală diferenței dintre niveluri", "Se emite un foton, dar λ crește când diferența de energie crește", "Se emite un foton cu energie egală cu energia nivelului final"], "ref": "Lucrări practice, p. 152"}, {"id": 50, "topic": 0, "q": "Identificați condițiile prevăzute de Legea lui Kirchhoff pentru existența corespondenței directe între spectrul de emisie și cel de absorbție.", "a": "Spectrele trebuie obținute în condiții identice; substanța absoarbe λ pe care le poate emite.", "e": "Atunci liniile negre de absorbție coincid cu cele luminoase de emisie.", "o": ["Specii diferite cu intensități egale, indiferent de energiile tranzițiilor", "Aceeași specie, dar perechi de niveluri cu diferențe energetice distincte", "Aceeași temperatură, indiferent de structura nivelurilor și de populațiile lor"], "ref": "Lucrări practice, p. 154 II. Radiația laser Lucrarea 22 – p. 180–191"}, {"id": 51, "topic": 1, "q": "Un atom aflat pe nivelul energetic inferior absoarbe un foton potrivit tranziției permise. Care este rezultatul interacțiunii?", "a": "Atomul se excită: electronul trece pe nivelul superior Es; fotonul e absorbit (dacă hν = Es – Ei).", "e": "Doar fotonul cu energia exact egală cu diferența nivelelor poate fi absorbit.", "o": ["Pompajul produce inversiunea populațiilor pe tranziția laser", "Fotonul nou are aceeași frecvență, fază, direcție și polarizare în modul stimulat", "Timpul de viață crescut permite acumularea particulelor pe nivelul laser superior"], "ref": "Lucrări practice, p. 180"}, {"id": 52, "topic": 1, "q": "Un foton întâlnește un atom excitat și determină emisie stimulată. Care este relația dintre fotonul incident și cel emis?", "a": "Fotonul emis are aceeași energie (frecvență), aceeași direcție și este în fază cu fotonul incident (coerent); fotonul incident nu e absorbit.", "e": "Rezultă 2 fotoni identici – baza amplificării laser.", "o": ["Aceeași frecvență și direcție, dar fază aleatorie", "Aceeași frecvență și fază, dar propagare obligatorie în sens opus", "Aceeași fază, dar frecvență dublă față de fotonul incident"], "ref": "Lucrări practice, p. 181"}, {"id": 53, "topic": 1, "q": "De ce favorizează starea metastabilă obținerea inversiunii populațiilor?", "a": "Pentru că atomul rămâne pe nivelul metastabil mult timp (~10⁻³ s față de ~10⁻⁷ s), astfel se acumulează mulți atomi excitați.", "e": "Atomii „stau” pe nivel și populația de sus devine mai mare decât cea de jos.", "o": ["Fotonul nou are aceeași frecvență, fază, direcție și polarizare în modul stimulat", "Pompajul produce inversiunea populațiilor pe tranziția laser", "Atomul trece pe nivelul superior, absorbind fotonul rezonant"], "ref": "Lucrări practice, p. 180–182"}, {"id": 54, "topic": 1, "q": "Într-un mediu activ aflat la echilibru termodinamic, absorbția poate domina emisia stimulată. Ce modificare favorizează amplificarea?", "a": "Inversiunea populațiilor (prin pompaj): majoritatea atomilor trebuie aduși în stare energetică superioară.", "e": "La echilibru fotonii emiși sunt absorbiți de atomii neexcitați.", "o": ["Creșterea populației nivelului inferior, cu populație superioară fixă", "Menținerea echilibrului termic și micșorarea secțiunii fasciculului", "Eliminarea oglinzii de ieșire fără a modifica populațiile mediului"], "ref": "Lucrări practice, p. 182"}, {"id": 55, "topic": 1, "q": "Un fascicul He–Ne vizibil are lungimea de undă de aproximativ 632,8 nm. În ce regiune spectrală se situează?", "a": "În domeniul vizibil – zona roșie (600–700 nm).", "e": "Spectrul vizibil ≈ 400–760 nm; 632,8 nm e roșu.", "o": ["Ultraviolet apropiat", "Infraroșu apropiat", "Verde, în spectrul vizibil"], "ref": "Lucrări practice, p. 155, 187"}, {"id": 56, "topic": 1, "q": "Un fascicul laser prezintă o distribuție spectrală foarte îngustă. Ce proprietate este evidențiată?", "a": "Monocromaticitatea.", "e": "Spectru foarte îngust – fotoni identici „copiați”.", "o": ["Coerența", "Direcționalitatea, manifestată prin divergență redusă", "E = hν = hc/λ, deci energia crește cu frecvența"], "ref": "Lucrări practice, p. 187"}, {"id": 57, "topic": 1, "q": "Două unde luminoase mențin un defazaj constant în timp. Ce proprietate exprimă această relație?", "a": "Coerența.", "e": "Coerență = aceeași frecvență și defazaj constant în timp.", "o": ["Monocromaticitatea", "Direcționalitatea, manifestată prin divergență redusă", "E = hν = hc/λ, deci energia crește cu frecvența"], "ref": "Lucrări practice, p. 188"}, {"id": 58, "topic": 1, "q": "Fasciculul laser iese aproape paralel cu axa rezonatorului. Ce proprietate explică această propagare?", "a": "Direcționalitatea.", "e": "Cavitatea rezonantă selectează fotonii care se propagă paralel cu axa ei.", "o": ["Monocromaticitatea", "Coerența", "Bandă îngustă, coerență, divergență mică și posibilitatea unei iradianțe mari"], "ref": "Lucrări practice, p. 187"}, {"id": 59, "topic": 1, "q": "Un fascicul monocromatic traversează o rețea cu fante echidistante. Care este cauza apariției maximelor luminoase pe ecran?", "a": "Difracția luminii pe fante și interferența razelor difractate; maximele apar la sin α = nλ/d.", "e": "Razele se dispersează sub diferite unghiuri și, datorită interferenței, formează maxime simetrice.", "o": ["Placă de sticlă cu striații paralele echidistante, cu d de ordinul 10⁻² mm", "Se măsoară L și S, se obține unghiul din tan θ = S/L, apoi λ = d sin θ/m", "tan θ = S/L, λ = d sin θ/m, ν = c/λ și E = hν"], "ref": "Lucrări practice, p. 185"}, {"id": 60, "topic": 1, "q": "Două lasere emit la lungimi de undă diferite. Care fascicul conține fotoni cu energie individuală mai mare?", "a": "Laserul cu lungimea de undă mai mică.", "e": "E = hc/λ – energia fotonului e invers proporțională cu λ.", "o": ["Cel cu lungimea de undă mai mare", "Cel cu putere mai mare indiferent de lungimea de undă", "Au energii egale dacă emit același număr de fotoni pe secundă"], "ref": "Lucrări practice, p. 186"}, {"id": 61, "topic": 1, "q": "Pentru stabilizarea unei rupturi retiniene se urmărește crearea unor puncte de aderență tisulară. Ce procedeu optic se potrivește?", "a": "Fotocoagularea cu laser („sudarea” retinei).", "e": "Laserul se folosește la dezlipiri sau rupturi retiniene; efectul termic coagulează țesutul.", "o": ["Ochelari de protecție adecvați lungimii de undă pentru persoanele expuse", "Ablație sau secționare precisă și coagulare locală pentru hemostază", "Monitorizarea neinvazivă a glicemiei, ca aplicație optică discutată în manual"], "ref": "Lucrări practice, p. 188"}, {"id": 62, "topic": 1, "q": "La pregătirea unei proceduri medicale cu laser, care măsură de protecție este indicată în manual pentru pacient și personal?", "a": "Atât personalul medical, cât și pacienții trebuie să poarte ochelari de protecție; activarea laserului se face cu o cheie ținută în loc sigur.", "e": "Protecția oculară se selectează în funcție de radiație. Ochelarii obișnuiți pot transmite lungimea de undă a laserului.", "o": ["Monitorizarea neinvazivă a glicemiei, ca aplicație optică discutată în manual", "Ablație sau secționare precisă și coagulare locală pentru hemostază", "Fotocoagularea laser retiniană"], "ref": "Lucrări practice, p. 189"}, {"id": 63, "topic": 1, "q": "Ce semnificație fizică exprimă acronimul provenit din limba engleză pentru noțiunea de LASER?", "a": "Light Amplification by Stimulated Emission of Radiation = amplificarea luminii prin emisia stimulată a radiației.", "e": "Numele descrie chiar principiul funcționării.", "o": ["Light Absorption by Spontaneous Emission of Radiation", "Light Amplification by Selective Excitation of Resonators", "Light Attenuation by Stimulated Emission of Radiation"], "ref": "Lucrări practice, p. 180"}, {"id": 64, "topic": 1, "q": "În ce condiții fizice un electron din învelișul atomic realizează o tranziție cuantică de absorbție de pe nivelul inferior Ei pe nivelul superior Es?", "a": "Când absoarbe un foton cu energia egală cu diferența nivelelor: hν = Es – Ei, adică ν = (Es – Ei)/h.", "e": "Altfel tranziția nu are loc.", "o": ["Starea metastabilă are viață mai lungă decât o stare excitată obișnuită", "Emisie stimulată, cu apariția unui foton suplimentar în același mod optic", "Nivelul superior al tranziției laser devine mai populat decât nivelul inferior, în modelul simplu"], "ref": "Lucrări practice, p. 180"}, {"id": 65, "topic": 1, "q": "Cum se compară timpul de viață al unui atom aflat în stare excitată obișnuită cu timpul de viață al unei stări metastabile?", "a": "Starea excitată obișnuită ~10⁻⁷ s; starea metastabilă ~10⁻³ s (mult mai lungă).", "e": "De circa 10 000 ori mai lungă.", "o": ["Nivelul metastabil se depopulează mai repede", "Ambele durate sunt egale la aceeași frecvență de emisie", "Nivelul metastabil are viață infinită și nu se poate dezexcita"], "ref": "Lucrări practice, p. 180"}, {"id": 66, "topic": 1, "q": "Prin ce se caracterizează procesul de emisie spontană la revenirea electronului de pe nivelul superior pe nivelul energetic inițial?", "a": "Electronul revine de la sine (spontan) pe nivelul inițial emițând un foton cu energia egală cu a fotonului absorbit; procesul e aleator, statistic.", "e": "Fotonii spontani au direcții și faze întâmplătoare.", "o": ["Light Amplification by Stimulated Emission of Radiation", "Starea metastabilă are viață mai lungă decât o stare excitată obișnuită", "Emisie stimulată, cu apariția unui foton suplimentar în același mod optic"], "ref": "Lucrări practice, p. 181"}, {"id": 67, "topic": 1, "q": "Ce fenomen fizic are loc atunci când un foton cu frecvența corespunzătoare tranziției interacționează cu un atom aflat pe un nivel metastabil?", "a": "Emisia stimulată.", "e": "Atomul e obligat să emită mai repede un foton identic cu cel incident.", "o": ["Starea metastabilă are viață mai lungă decât o stare excitată obișnuită", "Descărcarea excită He, ciocnirile transferă energie Ne, iar Ne emite stimulat", "Emisia are loc fără un foton declanșator, cu hν = E𝒔 − Eᵢ"], "ref": "Lucrări practice, p. 181"}, {"id": 68, "topic": 1, "q": "Ce modificare a distribuției energetice definește realizarea inversiunii populațiilor într-un mediu activ laser?", "a": "Majoritatea atomilor se află în stare energetică superioară: nivelele inferioare se depopulează, iar cele superioare (metastabile) se populează.", "e": "Stare de neechilibru termodinamic, menținută cu consum de energie (pompaj).", "o": ["Nivelul inferior trebuie să devină mai populat decât cel superior", "Ambele niveluri trebuie să aibă populații egale, indiferent de degenerescență", "Populațiile se păstrează la echilibru, iar frecvența este schimbată de oglinzi"], "ref": "Lucrări practice, p. 182"}, {"id": 69, "topic": 1, "q": "Ce criteriu energetic stă la baza selectării celor două gaze utilizate ca mediu activ în laserul cu heliu și neon?", "a": "Ambele gaze trebuie să posede nivele energetice egale sau foarte apropiate.", "e": "Astfel energia se poate transfera eficient prin ciocniri.", "o": ["Nivelul superior al tranziției laser devine mai populat decât nivelul inferior, în modelul simplu", "Descărcarea excită He, ciocnirile transferă energie Ne, iar Ne emite stimulat", "Atomul ocupă nivelul Eᵢ și absoarbe un foton cu hν = E𝒔 − Eᵢ într-o tranziție permisă"], "ref": "Lucrări practice, p. 183"}, {"id": 70, "topic": 1, "q": "Cum se realizează transferul de energie și emisia stimulată în amestecul gazos al laserului cu heliu- neon?", "a": "Descărcarea electrică excită atomii de He; prin ciocniri He transferă energia atomilor de Ne, populând nivelul metastabil al Ne; tranzițiile stimulate în cavitatea rezonantă dau fasciculul laser (632,8 nm).", "e": "Ne = gaz de bază; He = gaz adăugat.", "o": ["Emisie stimulată, cu apariția unui foton suplimentar în același mod optic", "Starea metastabilă are viață mai lungă decât o stare excitată obișnuită", "Nivelurile metastabile ale heliului sunt aproape rezonante cu nivelurile excitabile ale neonului"], "ref": "Lucrări practice, p. 183–184"}, {"id": 71, "topic": 1, "q": "Cum este alcătuită rețeaua optică de difracție utilizată în laborator și care este ordinul de mărime al constantei sale d?", "a": "Plăcuță de sticlă pe care cu un cuțit de diamant sunt trasate zgârieturi paralele și echidistante; d ≈ 10⁻² mm.", "e": "d = distanța dintre două zgârieturi vecine.", "o": ["Placă cu striații echidistante, cu d de ordinul 10⁻² m", "Placă cu striații aleatorii, cu d de ordinul 10⁻² mm", "Două oglinzi paralele, cu d egal cu lungimea rezonatorului"], "ref": "Lucrări practice, p. 185"}, {"id": 72, "topic": 1, "q": "Cum se determină lungimea de undă a radiației laser în lucrarea de laborator cu ajutorul rețelei de difracție?", "a": "Se măsoară L (rețea–ecran) și S (maxim central – maxim n); tg φ = S/L → se află sin φ; λ = d·sin φ / n (pentru n = 1: λ = d sin φ).", "e": "Apoi ν = c/λ și E = hν; se repetă pentru n = 2 și 3.", "o": ["Se măsoară L și S, apoi λ = d cos θ/m", "Se măsoară L și S, apoi λ = md sin θ", "Se folosește tan θ = L/S, apoi λ = d sin θ/m"], "ref": "Lucrări practice, p. 185–186"}, {"id": 73, "topic": 1, "q": "Ce proprietate fundamentală a radiației laser este definită prin emiterea de unde cu aceeași frecvență și cu un defazaj constant în timp?", "a": "Coerența.", "e": "Definiție.", "o": ["Monocromaticitatea", "Direcționalitatea, manifestată prin divergență redusă", "E = hν = hc/λ, deci energia crește cu frecvența"], "ref": "Lucrări practice, p. 188"}, {"id": 74, "topic": 1, "q": "Ce aplicație de diagnostic permite un dispozitiv laser care emite în infraroșu, înlocuind metoda clasică a recoltării probelor de sânge?", "a": "Determinarea substanțelor din sânge fără recoltare: glucoză, grăsimi (colesterol), acid uric, alcool.", "e": "Permite depistarea precoce a unor boli (diabet, tuberculoză etc.).", "o": ["Efecte de fotobiomodulare, cu obiective antalgice și de reparare tisulară", "Ablație sau secționare precisă și coagulare locală pentru hemostază", "Fotocoagulare pentru rupturi retiniene și anumite leziuni vasculare retiniene, respectiv aplicații în glaucom"], "ref": "Lucrări practice, p. 188"}, {"id": 75, "topic": 1, "q": "În ce intervenții din neurochirurgie și chirurgia vasculară sau digestivă își găsește aplicabilitate raza laser?", "a": "Tratarea glioamelor; desprinderea tumorilor de pe vase mari; vaporizarea tumorilor din ventricule; extirparea tumorilor cerebrale intens vascularizate; excizia nevroamelor; repararea și anastomozarea (sudura) vaselor; detașarea mușchilor de os; endoscopie pentru controlul hemoragiilor gastrointestinale; cicatrizarea ulcerului stomacal.", "e": "Raza laser = „bisturiu” fără sângerare.", "o": ["Efecte de fotobiomodulare, cu obiective antalgice și de reparare tisulară", "Monitorizarea neinvazivă a glicemiei, ca aplicație optică discutată în manual", "Fotocoagulare în leziuni retiniene și ablația selectivă a unor leziuni ORL"], "ref": "Lucrări practice, p. 188"}, {"id": 76, "topic": 1, "q": "Pentru ce patologii specifice este utilizată radiația laser în practica oftalmologică?", "a": "Retinopatia diabetică, ocluziile vaselor retiniene, prevenirea și extinderea hemoragiilor, dezlipiri sau rupturi retiniene, tumorile pleoapei, unele forme de cataractă și glaucom.", "e": "Tipul de laser și mecanismul diferă după țesutul țintă și procedură.", "o": ["Monitorizarea neinvazivă a glicemiei, ca aplicație optică discutată în manual", "Efecte de fotobiomodulare, cu obiective antalgice și de reparare tisulară", "Ablație sau secționare precisă și coagulare locală pentru hemostază"], "ref": "Lucrări practice, p. 188"}, {"id": 77, "topic": 1, "q": "Ce efecte biologice ale radiației laser sunt valorificate terapeutic în ortopedie și traumatologie?", "a": "Stimularea troficității țesuturilor, efect cicatrizant și antiinflamator.", "e": "Se tratează artroze, periartrite, osteoporoze, întârzieri de consolidare, spondiloze.", "o": ["Ablație sau secționare precisă și coagulare locală pentru hemostază", "Monitorizarea neinvazivă a glicemiei, ca aplicație optică discutată în manual", "Fotocoagulare în leziuni retiniene și ablația selectivă a unor leziuni ORL"], "ref": "Lucrări practice, p. 189"}, {"id": 78, "topic": 1, "q": "Care dintre următoarele afirmații descriu corect cuantificarea energiei și tranzițiile electronice din atom conform mecanicii cuantice?", "a": "Energia electronului/atomului ia numai valori discrete (nivele E1, E2…En); absorbția are loc doar dacă hν = Es – Ei; la absorbție electronul urcă (Ei→Es), la emisie coboară emițând foton.", "e": "Energia e „cuantificată” – în trepte.", "o": ["Pompaj optic, descărcare electrică sau injecție de curent, în funcție de mediul activ", "Distribuție de neechilibru menținută prin pompaj, favorabilă câștigului optic", "Viață relativ lungă, acumulare sub pompaj și facilitarea inversiunii"], "ref": "Lucrări practice, p. 180"}, {"id": 79, "topic": 1, "q": "Ce caracteristici definesc stările metastabile și rolul lor în generarea radiației laser?", "a": "Stări excitate în care electronul rămâne mult timp (~10⁻³ s); permit acumularea atomilor excitați (inversiunea populațiilor) și apoi emisia stimulată.", "e": "Fără ele nu se poate obține efectul laser.", "o": ["Aceeași frecvență, fază, direcție și polarizare în modul stimulat", "Distribuție de neechilibru menținută prin pompaj, favorabilă câștigului optic", "Niveluri discrete pentru stări legate și schimb de energie hν la tranziții radiative"], "ref": "Lucrări practice, p. 180–182"}, {"id": 80, "topic": 1, "q": "Prin ce proprietăți se caracterizează fotonii obținuți în procesul de emisie stimulată într-un mediu activ laser?", "a": "Au aceeași energie (frecvență), aceeași direcție și aceeași fază (sunt coerenți) cu fotonul stimulator.", "e": "Se multiplică în avalanșă.", "o": ["Viață relativ lungă, acumulare sub pompaj și facilitarea inversiunii", "Distribuție de neechilibru menținută prin pompaj, favorabilă câștigului optic", "Niveluri discrete pentru stări legate și schimb de energie hν la tranziții radiative"], "ref": "Lucrări practice, p. 181"}, {"id": 81, "topic": 1, "q": "Care sunt particularitățile fizice ale inversiunii populațiilor într-un sistem atomic?", "a": "Este o stare anormală, de neechilibru termodinamic; marea majoritate a atomilor e pe nivele superioare (metastabile); se menține doar cu consum de energie (pompaj); nu se obține prin simpla încălzire.", "e": "La orice temperatură nivelele de sus sunt mai puțin populate decât cele de jos.", "o": ["Pompaj optic, descărcare electrică sau injecție de curent, în funcție de mediul activ", "Viață relativ lungă, acumulare sub pompaj și facilitarea inversiunii", "Aceeași frecvență, fază, direcție și polarizare în modul stimulat"], "ref": "Lucrări practice, p. 182"}, {"id": 82, "topic": 1, "q": "Prin ce metode și mijloace fizice se realizează pompajul mediului activ pentru obținerea inversiunii populațiilor?", "a": "Pompaj fotonic (optic), electric sau chimic; la He-Ne – prin descărcare electrică în amestec.", "e": "Sursa care excită atomii = sursă de pompaj.", "o": ["Oglinzile oferă reacție optică, selectează moduri, iar una transmite o parte din fascicul", "Distribuție de neechilibru menținută prin pompaj, favorabilă câștigului optic", "Niveluri discrete pentru stări legate și schimb de energie hν la tranziții radiative"], "ref": "Lucrări practice, p. 182–183"}, {"id": 83, "topic": 1, "q": "Ce roluri îndeplinesc cavitatea rezonantă și oglinzile sale în funcționarea laserului?", "a": "Mențin fotonii mai mult timp în mediul activ și le lungesc traiectoria → amplificare; reflectă majoritatea fotonilor; oglinda de extracție (cu reflexie mai mică) lasă să iasă fasciculul; selectează fotonii paraleli cu axa (direcționalitate).", "e": "Două oglinzi paralele.", "o": ["Ambele oglinzi trebuie să fie complet transparente pentru a asigura reacția optică", "Cavitatea inversează populațiile fără pompaj, iar oglinzile introduc energia emisă", "Oglinzile absorb fotonii după o singură trecere și împiedică selectarea modurilor"], "ref": "Lucrări practice, p. 182"}, {"id": 84, "topic": 1, "q": "Care sunt etapele și relațiile matematice aplicate în lucrarea practică pentru determinarea lungimii de undă și a energiei cuantei laser?", "a": "Măsurarea L și S → tg φ = S/L → sin φ → λ = d sin φ / n → ν = c/λ (c = 3·10⁸ m/s) → E = hν (h = 6,62·10⁻³⁴ J·s); pentru n = 1, 2, 3; apoi valori medii.", "e": "Tabelul 22.1.", "o": ["Maxim central m = 0 și maxime simetrice ±m cu d sin θ = mλ", "Laser → rețea → ecran, maxime simetrice și tan θ = S/L", "Se măsoară L și S, se obține unghiul din tan θ = S/L, apoi λ = d sin θ/m"], "ref": "Lucrări practice, p. 185–186"}, {"id": 85, "topic": 1, "q": "Care sunt proprietățile fundamentale ale radiației laser și cum se definesc acestea?", "a": "Intensitatea (puterea fasciculului), monocromaticitatea (spectru foarte îngust), coerența (aceeași frecvență, defazaj constant), direcționalitatea (fascicul paralel).", "e": "Cele 4 proprietăți principale.", "o": ["Coerența permite interferometria, iar infraroșul permite evaluarea unor proprietăți optice tisulare", "Lungimea de undă, puterea pe suprafață, timpul de expunere și regimul pulsat sau continuu", "Bandă spectrală îngustă → monocromaticitate, fază stabilă → coerență, divergență mică → direcționalitate"], "ref": "Lucrări practice, p. 187–188"}, {"id": 86, "topic": 1, "q": "Cum se explică proprietatea de coerență a radiației laser și ce aplicații directe decurg din această proprietate și din emisia în infraroșu?", "a": "Coerența rezultă din emisia stimulată: se obțin fotoni identici cu cei care au produs stimularea → laserul e folosit la realizarea interferenței (holografie). Emisia în IR permite determinarea substanțelor din sânge fără recoltare.", "e": "Coerența ține de fază. Infraroșul desemnează o regiune spectrală și poate fi folosit în metode neinvazive.", "o": ["Bandă spectrală îngustă → monocromaticitate, fază stabilă → coerență, divergență mică → direcționalitate", "Bandă îngustă, coerență, divergență mică și posibilitatea unei iradianțe mari", "Energia pe foton este egală, iar fasciculul mai puternic transportă mai mulți fotoni pe secundă"], "ref": "Lucrări practice, p. 188"}, {"id": 87, "topic": 1, "q": "În ce afecțiuni oftalmologice și otorinolaringologice este indicat tratamentul cu radiație laser?", "a": "Oftalmologie: retinopatie diabetică, ocluzii vasculare retiniene, hemoragii, dezlipiri/rupturi retiniene, tumori ale pleoapei, cataractă, glaucom. ORL (fotocoagulare/vaporizare): papilomatoza laringiană, nodulii vocali, polipii corzilor vocale, formațiuni tumorale benigne.", "e": "Efectul urmărit variază de la coagulare la tăiere fină, în funcție de aplicație.", "o": ["Efecte de fotobiomodulare, cu obiective antalgice și de reparare tisulară", "Monitorizarea neinvazivă a glicemiei, ca aplicație optică discutată în manual", "Ablație sau secționare precisă și coagulare locală pentru hemostază"], "ref": "Lucrări practice, p. 188"}, {"id": 88, "topic": 1, "q": "Cum se corelează tranzițiile electronice dintre nivelele energetice (Ei și Es) cu procesele de absorbție, emisie spontană și emisie stimulată?", "a": "Absorbție: Ei → Es (hν = Es – Ei). Emisie spontană: Es → Ei de la sine, aleator. Emisie stimulată: Es → Ei forțat de un foton incident de aceeași frecvență, rezultând 2 fotoni identici.", "e": "În emisia stimulată intervine un foton rezonant. Emisia spontană nu cere un foton incident.", "o": ["Fotonul incident persistă, iar fotonul suplimentar ocupă același mod optic", "Nivel superior cu viață lungă, nivel inferior depopulat rapid și pompaj suficient", "Pompajul schimbă populațiile, iar inversiunea permite câștig optic"], "ref": "Lucrări practice, p. 180–181"}, {"id": 89, "topic": 1, "q": "Într-un sistem atomic cu stări metastabile, ce caracteristici favorizează amplificarea laser?", "a": "Timp de viață lung (~10⁻³ s), inversiunea populațiilor obținută prin pompaj, prezența cavității rezonante.", "e": "Așa fotonii stimulați se înmulțesc în avalanșă.", "o": ["Absorbția urcă electronul, iar emisia spontană și cea stimulată îl coboară", "Fotonul incident persistă, iar fotonul suplimentar ocupă același mod optic", "Pompajul schimbă populațiile, iar inversiunea permite câștig optic"], "ref": "Lucrări practice, p. 180–182"}, {"id": 90, "topic": 1, "q": "Un foton incident stimulează dezexcitarea unui atom din mediul activ. Ce proprietăți au fotonii implicați în proces?", "a": "Fotonul incident nu se absoarbe; cel emis are aceeași energie, direcție și fază (coerenți).", "e": "Rezultă 2 fotoni identici.", "o": ["Absorbția urcă electronul, iar emisia spontană și cea stimulată îl coboară", "Nivel superior cu viață lungă, nivel inferior depopulat rapid și pompaj suficient", "Pompajul schimbă populațiile, iar inversiunea permite câștig optic"], "ref": "Lucrări practice, p. 181"}, {"id": 91, "topic": 1, "q": "Se compară un mediu activ la echilibru cu unul supus pompajului. Ce schimbări caracterizează funcționarea laserului?", "a": "La echilibru: mai mulți atomi jos → fotonii sunt absorbiți, nu e amplificare. Cu pompaj: inversiunea populațiilor, emisia stimulată domină → amplificare (efect laser).", "e": "Pompajul consumă energie pentru menținerea inversiunii.", "o": ["Fotonul incident persistă, iar fotonul suplimentar ocupă același mod optic", "Absorbția urcă electronul, iar emisia spontană și cea stimulată îl coboară", "Nivel superior cu viață lungă, nivel inferior depopulat rapid și pompaj suficient"], "ref": "Lucrări practice, p. 182"}, {"id": 92, "topic": 1, "q": "În studiul fasciculului laser, ce relații între proprietăți și observații sunt corecte?", "a": "Spectru îngust ↔ monocromaticitate; fascicul paralel ↔ direcționalitate; tablou de interferență stabil ↔ coerență; puterea ↔ intensitatea.", "e": "Fiecare observație ilustrează o proprietate.", "o": ["Energia pe foton este egală, iar fasciculul mai puternic transportă mai mulți fotoni pe secundă", "Coerența permite interferometria, iar infraroșul permite evaluarea unor proprietăți optice tisulare", "Lungimea de undă, puterea pe suprafață, timpul de expunere și regimul pulsat sau continuu"], "ref": "Lucrări practice, p. 187–188"}, {"id": 93, "topic": 1, "q": "O rețea de difracție este iluminată normal cu un fascicul monocromatic. Ce caracteristici descriu maxima de pe ecran?", "a": "Maximele sunt simetrice față de maximul central (n = 0); poziția lor respectă sin α = nλ/d (ordinele ±1, ±2, ±3); depind de λ și de constanta rețelei d.", "e": "Figura: rețea 300 linii/mm (d = 1/300 mm).", "o": ["Maximul central are ordinul 1, iar celelalte maxime apar numai într-o parte", "Toate ordinele există pentru orice raport λ/d", "Maximele apar când d sin θ = (m + ½)λ"], "image": "../fig-93.png", "ref": "Lucrări practice, p. 185"}, {"id": 94, "topic": 1, "q": "După măsurarea lungimii de undă a unui laser, studentul interpretează energia fotonului. Ce relații fizice sunt corecte?", "a": "ν = c/λ; E = hν = hc/λ.", "e": "h = 6,62·10⁻³⁴ J·s; c = 3·10⁸ m/s.", "o": ["Divergența mică și posibilitatea focalizării la o pată mică", "Lungimea de undă, puterea pe suprafață, timpul de expunere și regimul pulsat sau continuu", "Energia pe foton este egală, iar fasciculul mai puternic transportă mai mulți fotoni pe secundă"], "ref": "Lucrări practice, p. 186"}, {"id": 95, "topic": 1, "q": "Se compară două fascicule laser cu aceeași lungime de undă, dar puteri diferite. Ce afirmații sunt compatibile cu această situație?", "a": "Fotonii au aceeași energie (E = hc/λ la fel); diferă puterea (intensitatea), adică energia transportată de fascicul – numărul de fotoni.", "e": "Energia unui foton depinde doar de λ.", "o": ["Fotonii din fasciculul mai puternic au energie mai mare", "Debitul de fotoni este identic, deoarece lungimea de undă este identică", "Puterea mai mare impune frecvență mai mare la aceeași lungime de undă"], "ref": "Lucrări practice, p. 186–187"}, {"id": 96, "topic": 1, "q": "În evaluarea aplicațiilor biomedicale, ce caracteristici ale radiației influențează interacțiunea cu țesuturile?", "a": "Lungimea de undă (gradul de penetrare intratisulară depinde de λ; roșul pătrunde 2–3 cm) și intensitatea/puterea (ex. până la 12 W pentru penetrare adâncă; max. 50 mW pentru tegumente și mucoase).", "e": "Cele mai folosite: roșu și infraroșu.", "o": ["Energia pe foton este egală, iar fasciculul mai puternic transportă mai mulți fotoni pe secundă", "Bandă spectrală îngustă → monocromaticitate, fază stabilă → coerență, divergență mică → direcționalitate", "Divergența mică și posibilitatea focalizării la o pată mică"], "ref": "Lucrări practice, p. 187"}, {"id": 97, "topic": 1, "q": "Pentru localizarea unui fascicul pe o țintă mică, ce proprietăți ale laserului sunt relevante?", "a": "Direcționalitatea (localizare fixă la nivel de microni) și monocromaticitatea.", "e": "Ex.: 220–300 orificii de 75–150 μm pe 1 cm² de piele.", "o": ["E = hν = hc/λ, deci energia crește cu frecvența", "Lungimea de undă, puterea pe suprafață, timpul de expunere și regimul pulsat sau continuu", "Energia pe foton este egală, iar fasciculul mai puternic transportă mai mulți fotoni pe secundă"], "ref": "Lucrări practice, p. 187"}, {"id": 98, "topic": 1, "q": "În chirurgie, selectați mecanismele sau efectele utilizate la prelucrarea laser a țesuturilor", "a": "Efect termic: coagulare (60–100°C) și volatilizare/vaporizare (>100°C); fotocoagulare; plus efecte foto-biostimulent și fotochimic.", "e": "Intervenții nesângerânde, fără complicații postoperatorii.", "o": ["Fotocoagulare în leziuni retiniene și ablația selectivă a unor leziuni ORL", "Efecte de fotobiomodulare, cu obiective antalgice și de reparare tisulară", "Monitorizarea neinvazivă a glicemiei, ca aplicație optică discutată în manual"], "ref": "Lucrări practice, p. 188; Prelegeri, p. 162–163"}, {"id": 99, "topic": 1, "q": "Pentru a explica un fascicul coerent obținut cu laserul He–Ne, selectați verigile procesului fizic corespunzătoare", "a": "Pompaj prin descărcare electrică → excitarea He → transfer de energie prin ciocniri la Ne → popularea nivelului metastabil (inversiunea populațiilor) → emisie stimulată → amplificare în cavitatea rezonantă (oglinzi) → fascicul coerent 632,8 nm, plan polarizat (ferestrele Brewster).", "e": "Lanțul complet al procesului.", "o": ["Pompajul ridică populația, relaxarea alimentează nivelul superior laser, iar tranziția radiantă are loc în jos", "Absorbție rezonantă, cu trecere de la nivelul inferior la cel superior", "Emisie spontană, cu trecere de la nivelul superior la cel inferior"], "ref": "Lucrări practice, p. 183–184"}, {"id": 100, "topic": 1, "q": "Analizând schema experimentală de difracție a radiației laser printr-o rețea de difracție, selectați afirmațiile corecte", "a": "Laserul, rețeaua de difracție și ecranul se pun pe bancul optic; pe ecran apar maxime luminoase (punct central n = 0 și maxime simetrice de ordinul 1, 2, 3) datorită difracției și interferenței; din L și S se determină λ.", "e": "Formula d sin θ = mλ leagă poziția maximului de lungimea de undă.", "o": ["Maxim central m = 0 și maxime simetrice ±m cu d sin θ = mλ", "tan θ = S/L, λ = d sin θ/m, ν = c/λ și E = hν", "Se măsoară L și S, se obține unghiul din tan θ = S/L, apoi λ = d sin θ/m"], "image": "../fig-100.png", "ref": "Lucrări practice, p. 185–186"}, {"id": 101, "topic": 1, "q": "Analizând diagrama nivelurilor energetice implicate în funcționarea laserului, selectați afirmațiile corecte", "a": "Atomii trec prin pompaj din starea de repaus în stare excitată (~10⁻⁷ s), apoi pe starea metastabilă (~10⁻³ s), unde se acumulează (inversiunea populațiilor); de aici prin emisie stimulată revin în starea de repaus emițând fotoni laser.", "e": "Pentru inversiune este util ca nivelul inferior laser să se depopuleze rapid.", "o": ["Excitare He prin descărcare, transfer către Ne, inversiune în Ne și amplificare în rezonator", "Absorbție rezonantă, cu trecere de la nivelul inferior la cel superior", "Emisie spontană, cu trecere de la nivelul superior la cel inferior"], "image": "../fig-101.png", "ref": "Lucrări practice, p. 181"}, {"id": 102, "topic": 1, "q": "Selectați afirmațiile care caracterizează fenomenul reprezentat în imagine", "a": "Emisia stimulată: un foton hν lovește atomul excitat, electronul coboară și ies 2 fotoni identici (aceeași energie, direcție, fază).", "e": "Baza efectului laser.", "o": ["Un foton este absorbit și nivelul superior devine ocupat", "Atomul excitat emite spontan un singur foton fără stimul", "Fotonul incident este anihilat simultan cu dezexcitarea, iar la ieșire nu rămâne radiație"], "image": "../fig-102.png", "ref": "Lucrări practice, p. 181"}, {"id": 103, "topic": 1, "q": "Analizând tranziția energetică reprezentată în imagine, selectați afirmațiile corecte", "a": "Emisie spontană: electronul coboară de la sine pe nivelul inferior emițând un foton hν = E2 – E1; proces aleator.", "e": "Nu există foton incident.", "o": ["Emisie stimulată cu apariția a doi fotoni în același mod", "Absorbție cu trecere pe nivelul energetic superior", "Împrăștiere elastică, fără modificarea stării atomului"], "image": "../fig-103.png", "ref": "Lucrări practice, p. 181"}, {"id": 104, "topic": 1, "q": "Selectați afirmațiile care caracterizează fenomenul reprezentat în imagine", "a": "Absorbție (excitare): atomul de pe E1 absoarbe fotonul hν = E2 – E1 și electronul urcă pe E2.", "e": "Fotonul dispare (e absorbit).", "o": ["Emisie spontană, cu coborârea electronului", "Emisie stimulată, cu doi fotoni la ieșire", "Împrăștiere elastică fără transfer de energie către atom"], "image": "../fig-104.png", "ref": "Lucrări practice, p. 180 III. Radioactivitatea. Detectarea radiațiilor nucleare Lucrările 24–25 – p. 199–221; Prelegeri, cap. 17"}, {"id": 105, "topic": 2, "q": "Ce este dezintegrarea radioactivă?", "a": "Fenomenul prin care nucleul unui atom instabil (radioizotop) se transformă spontan, degajând energie sub formă de radiații (α, β, pozitron, γ), într-un atom mai stabil.", "e": "Prin dezintegrare atomul pierde și o parte din masă.", "o": ["În condiții comparabile, particulele β pătrund mai mult decât α", "Fotoni electromagnetici de origine nucleară, fără sarcină", "Lanț de dezintegrări de la un radionuclid părinte către produși succesivi"], "ref": "Lucrări practice, p. 200"}, {"id": 106, "topic": 2, "q": "Care este componența particulei α?", "a": "2 protoni + 2 neutroni = nucleul de heliu ⁴₂He.", "e": "Are sarcină pozitivă (+2).", "o": ["Z scade cu 2, iar A scade cu 4", "n → p + e⁻ + antineutrino electronic", "Nucleu de heliu-4, cu sarcina +2e"], "ref": "Lucrări practice, p. 200"}, {"id": 107, "topic": 2, "q": "Care dintre afirmații diferențiază particulele α de particulele β prin capacitatea lor de pătrundere?", "a": "α pătrunde cel mai puțin (oprită de o foaie de hârtie sau ~1 inch de aer); β pătrunde mai bine (cel mult câțiva mm de aluminiu).", "e": "Particula α e grea și puternic încărcată.", "o": ["Fotoni electromagnetici de origine nucleară, fără sarcină", "Transformare spontană a unui nucleu instabil, însoțită de emisie nucleară", "Fotoni fără sarcină sau masă de repaus, nedeviați magnetic"], "ref": "Lucrări practice, p. 200–201"}, {"id": 108, "topic": 2, "q": "Ce caracterizează radiația γ?", "a": "Radiație electromagnetică cu cea mai mică λ și cea mai mare frecvență; trece prin aproape orice, e oprită doar de materiale grele (plumb); foarte periculoasă; detectabilă cu contorul Geiger.", "e": "Nu are sarcină și nici masă de repaus.", "o": ["În condiții comparabile, particulele β pătrund mai mult decât α", "Transformare spontană a unui nucleu instabil, însoțită de emisie nucleară", "Fotoni fără sarcină sau masă de repaus, nedeviați magnetic"], "ref": "Lucrări practice, p. 201"}, {"id": 109, "topic": 2, "q": "În urma unei dezintegrări α, cum se modifică numărul atomic Z și numărul de masă A ale nucleului rezultat?", "a": "Z scade cu 2, A scade cu 4.", "e": "ᴬ_Z X → ᴬ⁻⁴_{Z−2} Y + ⁴₂α.", "o": ["Z crește cu 1, iar A se păstrează", "Z scade cu 4, iar A scade cu 2", "Z scade cu 2, iar A se păstrează"], "ref": "Lucrări practice, p. 202"}, {"id": 110, "topic": 2, "q": "Cum se modifică nucleul în urma emisiei radiației γ?", "a": "Z și A nu se schimbă; nucleul trece din stare excitată (metastabilă) într-una mai stabilă, emițând energie.", "e": "γ = emisie de energie, nu de materie.", "o": ["Z crește cu 1, iar A se păstrează", "A scade cu 1 și Z rămâne constant", "Scade energia de excitare și Z scade cu 2"], "ref": "Lucrări practice, p. 203"}, {"id": 111, "topic": 2, "q": "Care dintre procesele nucleare este caracteristic pentru dezintegrarea β-?", "a": "Un neutron se transformă în proton + electron; electronul e expulzat ca particulă β⁻ (plus antineutrino).", "e": "ᴬ_Z X → ᴬ_{Z+1} Y + ⁰₋₁e + ν̃.", "o": ["Nucleu de heliu-4, cu sarcina +2e", "Un electron, în schema de dezintegrare β⁻", "Z scade cu 2, iar A scade cu 4"], "ref": "Lucrări practice, p. 202"}, {"id": 112, "topic": 2, "q": "Particula marcată „alfa” în poza alăturată corespunde:", "a": "Nucleului de heliu ⁴₂He (2 protoni + 2 neutroni).", "e": "În figură – grupul de 4 bile (2 roșii, 2 albastre).", "o": ["n → p + e⁻ + antineutrino electronic", "Un electron, în schema de dezintegrare β⁻", "Z scade cu 2, iar A scade cu 4"], "image": "../fig-112.png", "ref": "Lucrări practice, p. 201"}, {"id": 113, "topic": 2, "q": "În schema alăturată particula „beta”, emisă la dezintegrare este:", "a": "Un electron ⁰₋₁e (sarcină negativă).", "e": "În figură – o singură bilă.", "o": ["Nucleu de heliu-4, cu sarcina +2e", "n → p + e⁻ + antineutrino electronic", "Scade energia de excitare, cu A și Z constante"], "image": "../fig-113.png", "ref": "Lucrări practice, p. 201"}, {"id": 114, "topic": 2, "q": "Ce rol are detectorul de radiații nucleare?", "a": "Pune în evidență particulele nucleare, permite determinarea numărului lor și a unor caracteristici (energie, masă).", "e": "Definiție.", "o": ["Fir anodic central și catod cilindric coaxial", "Numărul impulsurilor sau rata de numărare", "1 Bq = 1 dezintegrare/s și 1 Ci = 3,7 × 10¹⁰ Bq"], "ref": "Lucrări practice, p. 204"}, {"id": 115, "topic": 2, "q": "Pentru un nucleu reprezentat prin notația ⁽ᴬ⁾₍Z₎X, Alegeți afirmația care descrie semnificația numerelor A și Z:", "a": "A – numărul de masă = numărul de nucleoni (protoni + neutroni); Z – numărul atomic = numărul de protoni.", "e": "N = A – Z = numărul de neutroni.", "o": ["Un electron, în schema de dezintegrare β⁻", "Scade energia de excitare, cu A și Z constante", "Z crește cu 1, iar A rămâne constant"], "ref": "Lucrări practice, p. 199"}, {"id": 116, "topic": 2, "q": "Un nucleu are numărul de masă A=27 și numărul atomic Z=13. Care afirmație descrie compoziția nucleului este adevărată?", "a": "13 protoni și 14 neutroni (27 nucleoni).", "e": "N = 27 – 13 = 14 (aluminiu ²⁷₁₃Al).", "o": ["14 protoni și 13 neutroni", "13 protoni și 27 neutroni", "27 protoni și 13 neutroni"], "ref": "Lucrări practice, p. 199"}, {"id": 117, "topic": 2, "q": "Un nucleu instabil suferă o dezintegrare β-. Cum se modifică numărul atomic Z și numărul de masă A ale nucleului rezultat?", "a": "Z crește cu 1, A rămâne același.", "e": "Un neutron devine proton.", "o": ["Z scade cu 1, A constant", "Z crește cu 1, A crește cu 1", "Z scade cu 2, A scade cu 4"], "ref": "Lucrări practice, p. 202"}, {"id": 118, "topic": 2, "q": "Cum sunt dispuși anodul și catodul în contorul Geiger–Müller?", "a": "Anodul – un fir foarte subțire (central); catodul – un cilindru metalic sau o peliculă metalică pe peretele interior al tubului de sticlă.", "e": "Formează un condensator cilindric.", "o": ["Numărul impulsurilor sau rata de numărare", "Transformă interacțiunile radiației cu detectorul în semnale măsurabile", "1 Bq = 1 dezintegrare/s și 1 Ci = 3,7 × 10¹⁰ Bq"], "ref": "Lucrări practice, p. 204"}, {"id": 119, "topic": 2, "q": "Radiația „gamma” este caracterizată prin:", "a": "Radiație electromagnetică cu λ foarte mică și frecvență foarte mare, foarte penetrantă, oprită de plumb/beton gros, nedeviată în câmp magnetic.", "e": "Rezultă de regulă din dezexcitarea nucleului după α sau β.", "o": ["α și β⁻ se curbează în sensuri opuse, iar γ nu este deviată", "Lanț de dezintegrări de la un radionuclid părinte către produși succesivi", "Fotoni electromagnetici de origine nucleară, fără sarcină"], "ref": "Lucrări practice, p. 201, 203"}, {"id": 120, "topic": 2, "q": "Ce informație furnizează contorul Geiger–Müller despre particulele înregistrate?", "a": "Doar numărul particulelor (le numără); nu permite determinarea altor proprietăți.", "e": "În regimul Geiger, amplitudinea impulsului nu oferă energia fiecărui eveniment.", "o": ["Energia fiecărei particule din înălțimea impulsului", "Sarcina electrică și masa fiecărei particule", "Activitatea exactă a sursei fără corecție pentru geometrie și eficiență"], "ref": "Lucrări practice, p. 205"}, {"id": 121, "topic": 2, "q": "Ce este o serie radioactivă?", "a": "Un șir de dezintegrări succesive (α și β) care începe cu un nucleu „cap de serie” instabil și se încheie cu un nucleu stabil.", "e": "4 familii: uraniu, thoriu, actiniu, neptuniu (toate se termină cu Pb).", "o": ["α și β⁻ se curbează în sensuri opuse, iar γ nu este deviată", "Fotoni fără sarcină sau masă de repaus, nedeviați magnetic", "Nucleele instabile emit spontan radiații α, β sau γ, după tipul tranziției"], "ref": "Lucrări practice, p. 203"}, {"id": 122, "topic": 2, "q": "Cum se comportă radiațiile α, β și γ într-un câmp magnetic?", "a": "α și β sunt deviate în sensuri opuse (au sarcini opuse); γ nu este deviată.", "e": "Forța magnetică depinde de semnul sarcinii și de orientarea vitezei și câmpului.", "o": ["Fotoni fără sarcină sau masă de repaus, nedeviați magnetic", "Lanț de dezintegrări de la un radionuclid părinte către produși succesivi", "Nucleele instabile emit spontan radiații α, β sau γ, după tipul tranziției"], "ref": "Lucrări practice, p. 203"}, {"id": 123, "topic": 2, "q": "În câmpul din figura alăturată, care radiație NU este deviată?", "a": "Radiația γ (fasciculul din mijloc).", "e": "Nu are sarcină electrică.", "o": ["Particulele α", "Particulele β⁻", "Atât particulele α, cât și cele β⁻"], "image": "../fig-123.png", "ref": "Lucrări practice, p. 203"}, {"id": 124, "topic": 2, "q": "Care dintre următoarele notații corespunde nucleului rezultat dintr-un nucleu instabil după o dezintegrare α?", "a": "ᴬ⁻⁴_{Z−2} Y.", "e": "Se pierd 2 protoni și 2 neutroni.", "o": ["A = Z + N și N = A − Z", "Z = 13, N = 14, A = 27, sarcină nucleară +13e", "Z crește cu 1, iar A rămâne constant"], "ref": "Lucrări practice, p. 202"}, {"id": 125, "topic": 2, "q": "Care sunt caracteristicile nucleului atomic?", "a": "Are toată sarcina pozitivă a atomului, ocupă centrul și concentrează practic toată masa; e format din protoni și neutroni (nucleoni) ținuți de forțe nucleare.", "e": "Dimensiunea nucleară este mult mai mică decât dimensiunea atomului.", "o": ["Nucleu de heliu-4, sarcină +2e, ionizare intensă și penetrare mică", "Un neutron devine proton, Z crește cu 1, N scade cu 1, A rămâne constant", "Z = 13, N = 14, A = 27, sarcină nucleară +13e"], "ref": "Lucrări practice, p. 199"}, {"id": 126, "topic": 2, "q": "Care este legătura dintre numărul de masă A, numărul atomic Z și numărul de neutroni N?", "a": "A = Z + N (deci N = A – Z).", "e": "Ex.: Al: 27 = 13 + 14.", "o": ["A = Z − N", "N = A + Z", "Z = A + N"], "ref": "Lucrări practice, p. 199"}, {"id": 127, "topic": 2, "q": "Pentru nucleul de aluminiu cu A=27 și Z=13, selectați afirmațiile corecte:", "a": "Al are 13 protoni, 14 neutroni, 27 nucleoni; notația ²⁷₁₃Al.", "e": "Exemplu din.", "o": ["Nucleul fiică are A − 4 și Z − 2", "Electron în β⁻ sau pozitron în β⁺, cu sarcina în modul e", "Sarcină +Ze, masă concentrată și structură alcătuită din nucleoni"], "ref": "Lucrări practice, p. 199"}, {"id": 128, "topic": 2, "q": "Care dintre enunțuri corespund fenomenului ilustrat în figura alăturată?", "a": "Radiațiile din sursa (U sau Th) din cutia de Pb trec printr-un câmp magnetic: particulele α și β se deviază în sensuri opuse, razele γ nu se deviază; pe ecranul cu ZnS apar trei pete luminoase.", "e": "Așa au fost numite istoric α, β, γ.", "o": ["Câmpul magnetic deviază numai fotonii gamma", "Toate cele trei componente sunt deviate în același sens", "Radiația beta negativă este neutră și își păstrează direcția"], "image": "../fig-128.png", "ref": "Lucrări practice, p. 203"}, {"id": 129, "topic": 2, "q": "Selectați afirmațiile despre materialele radioactive și radiațiile emise de acestea:", "a": "Materialul radioactiv emite spontan radiații (α, β, γ etc.); nucleul instabil le eliberează pentru a deveni stabil; fiecare tip de dezintegrare emite o particulă specifică; radiațiile sunt ionizante.", "e": "Emisiile diferă prin sarcină, masă, energie și capacitate de pătrundere.", "o": ["α este mai masivă și mai puternic ionizantă, β pătrunde în general mai mult", "Separă componentele încărcate prin devieri de semn opus și lasă γ pe direcția inițială", "Lanț de dezintegrări de la un radionuclid părinte către produși succesivi"], "ref": "Lucrări practice, p. 200"}, {"id": 130, "topic": 2, "q": "Caracteristicile particulei α sunt:", "a": "Nucleu de He (2p + 2n), sarcină pozitivă, penetrare mică (hârtie, ~1 inch aer); energie bine determinată (4–10 MeV) → spectru de linii; periculoasă dacă e emisă din interiorul corpului.", "e": "Masa relativ mare și sarcina dublă favorizează pierderea rapidă a energiei.", "o": ["Un neutron devine proton, Z crește cu 1, N scade cu 1, A rămâne constant", "Sarcină +Ze, masă concentrată și structură alcătuită din nucleoni", "Electron în β⁻ sau pozitron în β⁺, cu sarcina în modul e"], "ref": "Lucrări practice, p. 200–202"}, {"id": 131, "topic": 2, "q": "Ce modificări au loc în nucleul atomic la emisia unui electron în dezintegrarea β⁻?", "a": "Un neutron se transformă în proton și electron (expulzat); Z crește cu 1, A rămâne neschimbat.", "e": "Se emite și antineutrino.", "o": ["Nucleu de heliu-4, sarcină +2e, ionizare intensă și penetrare mică", "Electron în β⁻ sau pozitron în β⁺, cu sarcina în modul e", "Sarcină +Ze, masă concentrată și structură alcătuită din nucleoni"], "ref": "Lucrări practice, p. 202"}, {"id": 132, "topic": 2, "q": "Care sunt caracteristicile particulei β?", "a": "Electron cu sarcină negativă, relativ ușoară, pătrunde mai bine decât α (câțiva mm Al); energii de la 0 la Emax (spectru continuu); periculoasă, detectabilă cu contorul Geiger–Müller.", "e": "Spectrul energetic beta este continuu deoarece energia este împărțită cu un neutrino sau antineutrino.", "o": ["Nucleu de heliu-4, sarcină +2e, ionizare intensă și penetrare mică", "Rezultă un nucleu cu A − 4, Z − 2 și o particulă ⁴₂He", "Un neutron devine proton, Z crește cu 1, N scade cu 1, A rămâne constant"], "ref": "Lucrări practice, p. 200–202"}, {"id": 133, "topic": 2, "q": "Comparând particulele α și β, selectați afirmațiile adevărate:", "a": "α – sarcină +, grea, pătrundere minimă (hârtia o oprește); β – sarcină –, ușoară, pătrunde mai bine (o oprește sticla/plasticul subțire sau aluminiul). α are spectru de linii, β spectru continuu. În câmp magnetic se deviază opus.", "e": "α are sarcina +2e, iar β⁻ are sarcina −e. Câmpul le curbează diferit.", "o": ["Nucleele instabile emit spontan radiații α, β sau γ, după tipul tranziției", "Separă componentele încărcate prin devieri de semn opus și lasă γ pe direcția inițială", "α → nucleu de heliu, β⁻ → electron, γ → foton nuclear"], "ref": "Lucrări practice, p. 200–201"}, {"id": 134, "topic": 2, "q": "Selectați afirmațiile corecte despre unitățile de măsură ale activității unui preparat radioactiv:", "a": "Unitatea SI – becquerel (Bq) = 1 dezintegrare pe secundă; în practică – curie (Ci) = activitatea a 1 g de radiu; 1 Ci = 3,7·10¹⁰ Bq.", "e": "Activitatea este rata de dezintegrare. Gray și sievert exprimă mărimi de doză.", "o": ["1 Bq = 1 J/kg, 1 Ci = 3,7 × 10¹⁰ Bq", "1 Bq = 60 dezintegrări/s, 1 Ci = 3,7 × 10¹⁰ Bq", "1 Bq = 1 dezintegrare/s, 1 Ci = 3,7 × 10⁻¹⁰ Bq"], "ref": "Prelegeri, p. 187"}, {"id": 135, "topic": 2, "q": "Selectați asocierile dintre tipul radiației și caracteristicile corespunzătoare:", "a": "α – nucleu He, +, puțin penetrant; β – electron, –, penetrare medie; γ – undă electromagnetică, fără sarcină, foarte penetrantă (oprită de plumb).", "e": "Sarcinile sunt +2e, −e și zero.", "o": ["α → electron, β⁻ → nucleu de heliu, γ → foton", "α → nucleu de heliu, β⁻ → pozitron, γ → neutron", "α → proton, β⁻ → electron, γ → nucleu de heliu"], "ref": "Lucrări practice, p. 200–201, 215–216"}, {"id": 136, "topic": 2, "q": "Ce modificări au loc în nucleul atomic la emisia unei particule α?", "a": "Nucleul pierde 2 protoni și 2 neutroni: Z – 2, A – 4; devine alt element (cu 2 locuri mai la stânga în tabel).", "e": "Ex.: ²³⁸₉₂U → ²³⁴₉₀Th + ⁴₂He.", "o": ["Rezultă un nucleu cu A − 4, Z − 2 și o particulă ⁴₂He", "A se păstrează, Z crește cu unu și N scade cu unu", "În β⁻, n devine p, iar în β⁺, p devine n. A rămâne constant"], "ref": "Lucrări practice, p. 202"}, {"id": 137, "topic": 2, "q": "Ce transformări suferă un nucleu ⁽ᴬ⁾₍Z₎X după o dezintegrare α:", "a": "ᴬ_Z X → ᴬ⁻⁴_{Z−2} Y + ⁴₂He: numărul atomic scade cu 2, numărul de masă scade cu 4.", "e": "Se conservă sarcina și numărul de nucleoni.", "o": ["În β⁻, n devine p, iar în β⁺, p devine n. A rămâne constant", "A se păstrează, Z crește cu unu și N scade cu unu", "Electron în β⁻ sau pozitron în β⁺, cu sarcina în modul e"], "ref": "Lucrări practice, p. 202"}, {"id": 138, "topic": 2, "q": "Ce modificări ale nucleului și ce procese au loc în dezintegrarea β?", "a": "Neutron → proton + electron (β expulzat) + antineutrino; Z + 1, A neschimbat; energia β variază continuu de la 0 la Emax.", "e": "Ex.: ²³⁴₉₀Th → ²³⁴₉₁Pa + e⁻ + ν̃.", "o": ["Rezultă un nucleu cu A − 4, Z − 2 și o particulă ⁴₂He", "A se păstrează, Z crește cu unu și N scade cu unu", "Electron în β⁻ sau pozitron în β⁺, cu sarcina în modul e"], "ref": "Lucrări practice, p. 202"}, {"id": 139, "topic": 2, "q": "Un nucleu ⁽ᴬ⁾₍Z₎X suferă o dezintegrare β-. Selectați afirmațiile despre nucleul rezultat:", "a": "Nucleul rezultat: ᴬ_{Z+1} Y – are același A, un proton în plus și un neutron în minus; este alt element (un loc la dreapta).", "e": "Poate rămâne excitat și emite apoi γ.", "o": ["Rezultă un nucleu cu A − 4, Z − 2 și o particulă ⁴₂He", "În β⁻, n devine p, iar în β⁺, p devine n. A rămâne constant", "Se pierd doi protoni și doi neutroni"], "ref": "Lucrări practice, p. 202"}, {"id": 140, "topic": 2, "q": "Selectați afirmațiile care diferențiază dezintegrarea α de dezintegrarea β:", "a": "α: Z – 2, A – 4, emite nucleu de He, spectru de linii. β⁻: Z + 1, A neschimbat, emite electron (+ antineutrino), spectru continuu.", "e": "Diferențe principale.", "o": ["Poate fi un alt element după α sau β, ori același nucleu la energie mai mică după γ", "Emisie de fotoni la dezexcitare nucleară, fără schimbarea lui A și Z", "Produșii intermediari devin părinți pentru următoarele transformări"], "ref": "Lucrări practice, p. 202"}, {"id": 141, "topic": 2, "q": "Selectați afirmațiile despre radioactivitatea γ:", "a": "Nu e emisie de materie, ci de energie (radiație electromagnetică); rezultă din dezexcitarea nucleului (după α sau β) sau trecerea de la nivel metastabil la stabil; fotonii au energii de până la câțiva MeV; Z și A nu se modifică.", "e": "Poate urma unei emisii α sau β dacă nucleul fiică rămâne excitat.", "o": ["Produșii intermediari devin părinți pentru următoarele transformări", "Poate fi un alt element după α sau β, ori același nucleu la energie mai mică după γ", "În α se emite un nucleu de heliu cu ΔA = −4. În β se emite un lepton încărcat cu ΔA = 0"], "ref": "Lucrări practice, p. 203"}, {"id": 142, "topic": 2, "q": "Care sunt scopurile utilizării detectorilor de radiații nucleare?", "a": "Punerea în evidență a particulelor nucleare, numărarea lor, determinarea energiei sau masei; determinarea fondului radioactiv (cosmic) și dozimetrie.", "e": "Un detector spectrometric poate măsura energia, un Geiger obișnuit furnizează impulsuri de numărare.", "o": ["Detectează interacțiuni și le convertește în semnale ce pot fi numărate sau analizate", "Detectarea depinde de interacțiunea radiației cu mediul sensibil și de eficiența aparatului", "Cilindru catodic, fir anodic, gaz de umplere, tensiune înaltă și circuit de citire"], "ref": "Lucrări practice, p. 204–207"}, {"id": 143, "topic": 2, "q": "Nucleul rezultat în urma unei dezintegrări radioactive:", "a": "E nucleul altui element chimic (alt loc în tabelul Mendeleev) și nu este în toate cazurile stabil – poate continua dezintegrarea (serie).", "e": "Se respectă conservarea sarcinii și a numărului de nucleoni.", "o": ["În α se emite un nucleu de heliu cu ΔA = −4. În β se emite un lepton încărcat cu ΔA = 0", "Produșii intermediari devin părinți pentru următoarele transformări", "Emisie de fotoni la dezexcitare nucleară, fără schimbarea lui A și Z"], "ref": "Lucrări practice, p. 202–203"}, {"id": 144, "topic": 2, "q": "Ce caracteristici au transformările nucleelor unei serii radioactive?", "a": "Transformări succesive prin emisii α sau β, de la un nucleu cap de serie instabil până la unul stabil (Pb); viteza seriei e dată de nucleul care se dezintegrează cel mai lent.", "e": "Ex.: U-238 → Pb-206 prin 19 dezintegrări.", "o": ["Emisie de fotoni la dezexcitare nucleară, fără schimbarea lui A și Z", "Poate fi un alt element după α sau β, ori același nucleu la energie mai mică după γ", "În α se emite un nucleu de heliu cu ΔA = −4. În β se emite un lepton încărcat cu ΔA = 0"], "ref": "Lucrări practice, p. 199–203"}, {"id": 145, "topic": 2, "q": "Care sunt caracteristicile numărului atomic al nucleului?", "a": "Z = numărul de protoni din nucleu = numărul de ordine al elementului în tabelul Mendeleev (= numărul de electroni în atomul neutru).", "e": "Determină elementul chimic.", "o": ["În β⁻, n devine p, iar în β⁺, p devine n. A rămâne constant", "A se păstrează, Z crește cu unu și N scade cu unu", "Un neutron devine proton, Z crește cu 1, N scade cu 1, A rămâne constant"], "ref": "Lucrări practice, p. 199"}, {"id": 146, "topic": 2, "q": "Care sunt funcțiile unui detector de radiații nucleare?", "a": "Detectarea particulelor, numărarea lor, determinarea energiei sau masei.", "e": "Tipul de informație depinde de principiul detectorului și de calibrare.", "o": ["Cilindru catodic, fir anodic, gaz de umplere, tensiune înaltă și circuit de citire", "Detectarea depinde de interacțiunea radiației cu mediul sensibil și de eficiența aparatului", "Detectarea prezenței radiației, numărarea evenimentelor și măsurători specifice aparatului"], "ref": "Lucrări practice, p. 204"}, {"id": 147, "topic": 2, "q": "Care sunt elementele constructive ale contorului Geiger–Müller?", "a": "Tub de sticlă cu gaz, condensator cilindric: anod – fir foarte subțire, catod – cilindru metalic/peliculă; sursă de tensiune de câteva sute de volți; rezistorul R; sistem de amplificare și înregistrare.", "e": "Gazul și electrozii permit multiplicarea sarcinilor formate prin ionizare.", "o": ["Detectează interacțiuni și le convertește în semnale ce pot fi numărate sau analizate", "Detectarea depinde de interacțiunea radiației cu mediul sensibil și de eficiența aparatului", "Bloc de bază cu alimentare și numărător, plus bloc detector cu contor Geiger–Müller"], "ref": "Lucrări practice, p. 204–205"}, {"id": 148, "topic": 2, "q": "Selectați afirmațiile despre detectarea radiațiilor nucleare:", "a": "Detectoarele se bazează pe: ionizarea în gaz (camera de ionizare, contor Geiger– Müller); scintilații (cristal NaI(Tl) + fotomultiplicator); perechi electron-gol în semiconductori (amplitudinea impulsului ∝ energia).", "e": "Rata înregistrată poate fi mai mică decât rata de emisie din cauza geometriei și eficienței.", "o": ["Fiecare nucleu dezintegrat produce obligatoriu un impuls în orice detector", "Eficiența este identică pentru toate radiațiile, indiferent de energie", "Detectorul Geiger măsoară direct masa particulei din amplitudinea impulsului"], "ref": "Lucrări practice, p. 204–206"}, {"id": 149, "topic": 2, "q": "Ce procese au loc la trecerea unei particule nucleare încărcate prin gazul contorului Geiger–Müller?", "a": "Se produc perechi ion–electron; electronii sunt puternic accelerați lângă anod și produc ionizări secundare → avalanșă de ioni și electroni → curent de descărcare scurt.", "e": "Câmpul transferă electronilor suficientă energie pentru ionizări secundare.", "o": ["Apar perechi ion–electron și apoi multiplicare prin ionizare secundară", "Sarcinile colectate după avalanșă generează un impuls în circuit", "Cilindru catodic, fir anodic, gaz de umplere, tensiune înaltă și circuit de citire"], "ref": "Lucrări practice, p. 204–205"}, {"id": 150, "topic": 2, "q": "Cum se formează semnalul în contorul Geiger–Müller?", "a": "Curentul de descărcare produce pe rezistorul R o cădere de tensiune (impuls), care este amplificată și înregistrată – un impuls pentru fiecare particulă.", "e": "Stingerea descărcării pregătește tubul pentru următorul eveniment.", "o": ["Apar perechi ion–electron și apoi multiplicare prin ionizare secundară", "Ionizare primară, accelerarea electronilor, avalanșă și impuls electric", "Gazul se ionizează pe traiectorie și produce electroni liberi și ioni pozitivi"], "ref": "Lucrări practice, p. 204–205"}, {"id": 151, "topic": 2, "q": "Ce fenomene se produc în gazul contorului Geiger–Müller la trecerea unei particule încărcate?", "a": "Ionizare primară (perechi ion–electron), accelerarea electronilor în câmpul intens de lângă anod, ionizare secundară, avalanșă, descărcare de scurtă durată.", "e": "În regimul Geiger, descărcarea se propagă, iar circuitul înregistrează un singur impuls.", "o": ["Ionizare primară, accelerarea electronilor, avalanșă și impuls electric", "Sarcinile colectate după avalanșă generează un impuls în circuit", "Gazul se ionizează pe traiectorie și produce electroni liberi și ioni pozitivi"], "ref": "Lucrări practice, p. 204–205"}, {"id": 152, "topic": 2, "q": "Care sunt elementele constructive ale instalației B-4, utilizată pentru determinarea fondului cosmic?", "a": "Două blocuri: blocul de bază (alimentarea contorului G–M cu tensiune înaltă + circuitele de numărare/înregistrare, cu 6 decatroane) și blocul contoarelor (contorul Geiger–Müller).", "e": "Lanțul de măsurare al instalației B-4 include alimentarea de înaltă tensiune și circuite de numărare.", "o": ["Gazul se ionizează pe traiectorie și produce electroni liberi și ioni pozitivi", "Cilindru catodic, fir anodic, gaz de umplere, tensiune înaltă și circuit de citire", "Apar perechi ion–electron și apoi multiplicare prin ionizare secundară"], "ref": "Lucrări practice, p. 206"}, {"id": 153, "topic": 2, "q": "Ce se întâmplă la trecerea unei particule încărcate prin gazul unui detector?", "a": "Se formează perechi ion–electron care sunt colectate de doi electrozi aflați sub diferență de potențial → curent (impuls).", "e": "Tensiunea trebuie să fie suficientă ca să nu se recombine ionii.", "o": ["Bloc de bază cu alimentare și numărător, plus bloc detector cu contor Geiger–Müller", "Apar perechi ion–electron și apoi multiplicare prin ionizare secundară", "Ionizare primară, accelerarea electronilor, avalanșă și impuls electric"], "ref": "Lucrări practice, p. 204"}, {"id": 154, "topic": 2, "q": "Ce observații corespund fenomenului ilustrat în figura alăturată?", "a": "În câmpul magnetic: particulele α se deviază într-o parte, β în partea opusă, razele γ trec nedeviate; fiecare lovește ecranul cu ZnS în alt loc.", "e": "Separarea după sarcină.", "o": ["Toate componentele urmează același traseu deoarece au aceeași sarcină", "Câmpul deviază componenta neutră și lasă nedeviate componentele încărcate", "Direcția de deviere depinde numai de energie, independent de semnul sarcinii"], "image": "../fig-154.png", "ref": "Lucrări practice, p. 203"}, {"id": 155, "topic": 2, "q": "Ce observație rezultă din dezintegrarea ilustrată în figura alăturată?", "a": "²³⁸₉₂U emite o particulă α și se transformă în ²³⁴₉₀Th: Z scade cu 2, A scade cu 4.", "e": "Nucleu părinte → nucleu fiică + α.", "o": ["Uraniul-238 emite un electron și formează neptuniu-238", "Uraniul-238 emite γ și formează toriu-234", "Uraniul-238 emite un neutron și formează toriu-237"], "image": "../fig-155.png", "ref": "Lucrări practice, p. 202"}, {"id": 156, "topic": 2, "q": "Ce afirmații sunt e despre cutia din plumb reprezentată în figura alăturată?", "a": "În cutia de plumb se află sursa radioactivă (U sau Th); plumbul absoarbe radiațiile (protecție), iar radiațiile ies doar printr-un orificiu îngust, sub formă de fascicul.", "e": "Plumbul oprește eficient chiar și γ.", "o": ["În dezintegrarea α a uraniului-238 apare toriu-234 și se emite un nucleu de heliu-4.", "Separă componentele încărcate prin devieri de semn opus și lasă γ pe direcția inițială", "Poate fi un alt element după α sau β, ori același nucleu la energie mai mică după γ"], "image": "../fig-156.png", "ref": "Lucrări practice, p. 203"}, {"id": 157, "topic": 2, "q": "În montajul ilustrat în figura alăturată, radiațiile emise de sursa radioactivă traversează un câmp magnetic înainte de a ajunge pe ecran. Care este rolul câmpului magnetic în această experiență?", "a": "Separă radiațiile după sarcina lor: α și β sunt deviate în sensuri opuse, γ nu – astfel se identifică tipurile de radiații.", "e": "Forța Lorentz permite diferențierea α de β⁻ după semnul sarcinii.", "o": ["Plumbul atenuează radiația în direcțiile nedorite, iar orificiul colimează fasciculul", "În dezintegrarea α a uraniului-238 apare toriu-234 și se emite un nucleu de heliu-4.", "Poate fi un alt element după α sau β, ori același nucleu la energie mai mică după γ"], "image": "../fig-157.png", "ref": "Lucrări practice, p. 203 IV. Polarizarea luminii. Polarimetria Lucrarea 20 – p. 162–173"}, {"id": 158, "topic": 3, "q": "Identificați componenta undei electromagnetice de care este legată acțiunea chimică și cea biologică a luminii asupra ochiului.", "a": "Componenta electrică – vectorul E (vectorul luminii).", "e": "De aceea E e caracteristica de bază a luminii.", "o": ["Efectul fotoelectric", "Domeniul vizibil", "Orientarea transversală a vectorului E fluctuează statistic fără o direcție preferată"], "ref": "Lucrări practice, p. 163"}, {"id": 159, "topic": 3, "q": "Identificați vectorii care caracterizează unda electromagnetică.", "a": "Vectorul intensității câmpului electric E și vectorul intensității câmpului magnetic H.", "e": "Oscilează în plane perpendiculare, ambele conținând direcția de propagare.", "o": ["Incidență la unghiul Brewster, cu tan θᴮ = n₂/n₁ și raze reflectată și refractată perpendiculare", "Orientarea transversală a vectorului E fluctuează statistic fără o direcție preferată", "Vectorul E are modul constant și vârful său descrie un cerc în plan transversal"], "ref": "Lucrări practice, p. 162"}, {"id": 160, "topic": 3, "q": "Definiți lumina nepolarizată.", "a": "Lumina în care oscilațiile vectorului E au loc în plane diferite, orientate haotic (lumina naturală).", "e": "Undele sunt emise de miliarde de atomi orientați haotic.", "o": ["Incidență la unghiul Brewster, cu tan θᴮ = n₂/n₁ și raze reflectată și refractată perpendiculare", "Vectorul E are modul constant și vârful său descrie un cerc în plan transversal", "Vectorul electric E și vectorul magnetic B, transversali și reciproc perpendiculari pentru o undă plană în vid"], "ref": "Lucrări practice, p. 163"}, {"id": 161, "topic": 3, "q": "Identificați fenomenul care evidențiază proprietățile corpusculare ale luminii.", "a": "Efectul fotoelectric (și efectul Compton) – fenomenele de emisie și absorbție.", "e": "Proprietățile corpusculare se văd la emisie/absorbție.", "o": ["Vectorul câmpului electric E", "Domeniul vizibil", "tan θᴮ = n₂/n₁"], "ref": "Lucrări practice, p. 163"}, {"id": 162, "topic": 3, "q": "Precizați condiția de polarizare totală a razei reflectate prin legea lui Brewster.", "a": "tg i = n (tangenta unghiului de incidență = indicele de refracție al mediului).", "e": "Atunci unghiul dintre raza reflectată și cea refractată e 90°.", "o": ["Incidență normală, cu raze reflectată și refractată coliniare", "Incidență la unghiul critic, cu refracție la 90°", "Incidență cu tan θᴮ = n₁/n₂ și raze paralele"], "ref": "Lucrări practice, p. 164"}, {"id": 163, "topic": 3, "q": "Identificați raza care traversează practic nedeviată prisma Nicol.", "a": "Raza extraordinară.", "e": "Balsamul de Canada are pentru ea un indice foarte apropiat de cel al spatului.", "o": ["Balsam de Canada", "Zero în modelul ideal", "Reflexie totală internă a razei ordinare"], "ref": "Lucrări practice, p. 164–165"}, {"id": 164, "topic": 3, "q": "Definiți activitatea optică.", "a": "Proprietatea unor substanțe de a roti planul de polarizare al luminii incidente.", "e": "Datorată atomilor de C asimetrici.", "o": ["Metodă de măsurare a rotației optice a luminii liniar polarizate", "Rotația specifică a substanței, pentru temperatură și lungime de undă precizate", "Spre dreapta, în convenția de observare a manualului"], "ref": "Lucrări practice, p. 167"}, {"id": 165, "topic": 3, "q": "Definiți lumina circular polarizată.", "a": "Lumina la care extremitatea vectorului de lumină descrie un cerc.", "e": "Două componente ortogonale cu amplitudini egale și defazaj ±π/2 produc polarizare circulară.", "o": ["Orientarea transversală a vectorului E fluctuează statistic fără o direcție preferată", "Incidență la unghiul Brewster, cu tan θᴮ = n₂/n₁ și raze reflectată și refractată perpendiculare", "Vectorul electric E și vectorul magnetic B, transversali și reciproc perpendiculari pentru o undă plană în vid"], "ref": "Lucrări practice, p. 168"}, {"id": 166, "topic": 3, "q": "Precizați sensul de rotație a planului de polarizare pentru o substanță dextrogiră.", "a": "Spre dreapta (substanță dextrogiră).", "e": "Ex.: glucoza, lactoza, alanina, progesteronul.", "o": ["Spre stânga", "Direcția variază cu lungimea tubului", "Direcția depinde de orientarea axei analizorului"], "ref": "Lucrări practice, p. 167"}, {"id": 167, "topic": 3, "q": "Identificați mărimea notată l în relația φ = [α]·C·l / 100.", "a": "l – lungimea stratului de soluție străbătut (lungimea tubului), în dm.", "e": "C în % (g/100 cm³).", "o": ["Rotația specifică a substanței, pentru temperatură și lungime de undă precizate", "Rotește polarizarea în porțiunea centrală, creând câmpuri comparabile pentru reglaj precis", "Capacitatea unei substanțe de a roti planul luminii liniar polarizate"], "ref": "Lucrări practice, p. 167"}, {"id": 168, "topic": 3, "q": "Identificați semnificația mărimii [α] în relația φ = [α]·C·l / 100.", "a": "[α] – unghiul de rotire specifică al substanței optic active (determinat la 20°C și λ = 589,4 nm, linia D a sodiului).", "e": "Ex.: glucoză +52,75; fructoză –92.", "o": ["Lungimea stratului de soluție străbătut, exprimată în dm pentru formula cu C în g/100 mL", "Metodă de măsurare a rotației optice a luminii liniar polarizate", "Rotește polarizarea în porțiunea centrală, creând câmpuri comparabile pentru reglaj precis"], "ref": "Lucrări practice, p. 167"}, {"id": 169, "topic": 3, "q": "Definiți polarimetria.", "a": "Metoda de analiză calitativă și cantitativă a substanțelor optic active cu lumină polarizată, bazată pe măsurarea unghiului cu care soluția rotește planul luminii polarizate.", "e": "Cunoscând rotația specifică și lungimea tubului, se poate determina concentrația.", "o": ["Rotația specifică a substanței, pentru temperatură și lungime de undă precizate", "Capacitatea unei substanțe de a roti planul luminii liniar polarizate", "Spre dreapta, în convenția de observare a manualului"], "ref": "Lucrări practice, p. 168"}, {"id": 170, "topic": 3, "q": "Precizați mărimea măsurată direct cu polarimetrul.", "a": "Unghiul de rotire φ al planului de polarizare (din el se calculează concentrația).", "e": "φ = φ′ – φ₀.", "o": ["Tubul ce conține soluția", "Sursa de lumină LED", "Ocularul"], "ref": "Lucrări practice, p. 168–169"}, {"id": 171, "topic": 3, "q": "Precizați rolul lamelei de cuarț din diafragma polarimetrului.", "a": "Permite citirea fotometrică a unghiurilor cu mai mare precizie: lasă să treacă doar razele centrale și rotește planul cu 5–7°, astfel câmpul vizual se împarte în trei părți (câmp triplu).", "e": "Se caută iluminarea uniformă.", "o": ["Lungimea stratului de soluție străbătut, exprimată în dm pentru formula cu C în g/100 mL", "Rotația specifică a substanței, pentru temperatură și lungime de undă precizate", "Metodă de măsurare a rotației optice a luminii liniar polarizate"], "ref": "Lucrări practice, p. 169–170"}, {"id": 172, "topic": 3, "q": "Identificați din figură, domeniul plasat între ultraviolet și infraroșu.", "a": "Domeniul vizibil (spectrul vizibil, ≈ 400–700 nm).", "e": "UV – λ mai mici, IR – λ mai mari.", "o": ["tan θᴮ = n₂/n₁", "Efectul fotoelectric", "Lumina nepolarizată, cu orientări multiple ale lui E"], "image": "../fig-172.png", "ref": "Lucrări practice, p. 163"}, {"id": 173, "topic": 3, "q": "Identificați tipul luminii reprezentate în schema a).", "a": "Lumină naturală (nepolarizată) – vectorii E în toate direcțiile.", "e": "În schema a), direcțiile transversale diferite simbolizează fluctuațiile orientării câmpului.", "o": ["Lumină fără o orientare transversală preferată a câmpului electric", "Domeniul vizibil", "Vectorul E are modul constant și vârful său descrie un cerc în plan transversal"], "image": "../fig-173.png", "ref": "Lucrări practice, p. 163"}, {"id": 174, "topic": 3, "q": "Identificați din imagine, componenta marcată cu cifra 6.", "a": "6 – tubul cu soluție.", "e": "Polarimetrul P1000LED, Fig. 20.9.", "o": ["Ocularul", "Sursa LED", "Scara și vernierul"], "image": "../fig-174.png", "ref": "Lucrări practice, p. 169"}, {"id": 175, "topic": 3, "q": "Precizați aspectul câmpului vizual în schema b) din figură.", "a": "Câmp vizual uniform iluminat peste tot (poziția de măsurare).", "e": "În schema b), analizorul a fost rotit până la egalizarea iluminării centrale și laterale.", "o": ["Centru luminos și regiuni laterale întunecate", "Centru întunecat și regiuni laterale luminoase", "Extincție completă în tot câmpul"], "image": "../fig-175.png", "ref": "Lucrări practice, p. 170"}, {"id": 176, "topic": 3, "q": "Identificați din imagine, componenta marcată cu cifra 2.", "a": "2 – ocularul.", "e": "Ocularul permite observarea câmpului împărțit în regiuni.", "o": ["Tubul cu soluție", "Sursa LED", "Scara și vernierul"], "image": "../fig-176.png", "ref": "Lucrări practice, p. 169"}, {"id": 177, "topic": 3, "q": "Identificați din imagine, componenta marcată cu cifra 7.", "a": "7 – lumina LED (sursa de lumină).", "e": "Aceasta iluminează montajul polarimetric.", "o": ["Polarizorul", "Ocularul", "Tubul cu soluție"], "image": "../fig-177.png", "ref": "Lucrări practice, p. 169"}, {"id": 178, "topic": 3, "q": "Definiți lumina nepolarizată.", "a": "Lumina naturală, în care vectorul E oscilează în plane diferite, orientate haotic.", "e": "Un polarizor ideal transmite în medie jumătate din intensitatea ei.", "o": ["Lumina nepolarizată, cu orientări multiple ale lui E", "Reflexie, dublă refracție și absorbție selectivă prin dicroism", "Interferență, difracție și polarizare"], "ref": "Lucrări practice, p. 163"}, {"id": 179, "topic": 3, "q": "Identificați expresia matematică a legii lui Brewster pentru polarizarea totală prin reflexie.", "a": "tg i = n.", "e": "Legea lui Brewster (i + r = 90°).", "o": ["sin θᴮ = n₂/n₁", "tan θᴮ = n₁/n₂", "cos θᴮ = n₂/n₁"], "ref": "Lucrări practice, p. 164"}, {"id": 180, "topic": 3, "q": "Precizați substanța utilizată pentru lipirea celor două jumătăți ale cristalului de spat de Islanda în construcția nicolului.", "a": "Balsamul de Canada.", "e": "Cristalul e tăiat pe diagonala scurtă și lipit.", "o": ["Zero în modelul ideal", "Reflexie totală internă a razei ordinare", "Sulfat de iodochinină, denumit herapatit"], "ref": "Lucrări practice, p. 164"}, {"id": 181, "topic": 3, "q": "În imaginea alăturată, identificați fenomenul pe care îl suferă raza ordinară la suprafața de separație cu balsamul de Canada în nicol.", "a": "Reflexie totală (raza ordinară e eliminată lateral).", "e": "Pentru ea balsamul are indice mult mai mic decât spatul.", "o": ["Sulfat de iodochinină, denumit herapatit", "Zero în modelul ideal", "Balsam de Canada"], "image": "../fig-181.png", "ref": "Lucrări practice, p. 165"}, {"id": 182, "topic": 3, "q": "Precizați denumirea chimică a cristalelor dicroice de herapatit folosite la fabricarea polaroizilor.", "a": "Sulfat de iodochinină.", "e": "Cristale aciculare, orientate paralel, în matriță de plastic.", "o": ["Reflexie totală internă a razei ordinare", "Zero în modelul ideal", "Balsam de Canada"], "ref": "Lucrări practice, p. 165"}, {"id": 183, "topic": 3, "q": "Determinați intensitatea luminii transmise atunci când polarizorul și analizorul sunt încrucișați la un unghi de 90°.", "a": "Intensitatea este nulă (zero) – lumina nu trece.", "e": "Polarizor și analizor încrucișați.", "o": ["I₀/2", "I₀", "I₀/√2"], "image": "../fig-183.png", "ref": "Lucrări practice, p. 166–167"}, {"id": 184, "topic": 3, "q": "Definiți substanțele optic active.", "a": "Substanțe (mai ales organice, cu atomi de C asimetrici) care rotesc planul de polarizare al luminii.", "e": "Pot fi dextrogire sau levogire.", "o": ["Glucoza, lactoza, alanina și progesteronul, ca exemple din manual", "Natura substanței, lungimea de undă, temperatura și mediul de măsurare", "Fructoza, serina și colesterolul, ca exemple din manual"], "ref": "Lucrări practice, p. 167"}, {"id": 185, "topic": 3, "q": "Precizați fenomenele fizice în care se manifestă proprietățile ondulatorii ale luminii.", "a": "Reflexie, refracție, interferență, difracție, polarizare (fenomenele de propagare).", "e": "Interferența și difracția arată superpoziția undelor, iar polarizarea arată caracterul transversal.", "o": ["Efect fotoelectric și efect Compton", "Reflexie, dublă refracție și absorbție selectivă prin dicroism", "tan θᴮ = n₂/n₁"], "ref": "Lucrări practice, p. 163"}, {"id": 186, "topic": 3, "q": "Precizați fenomenele fizice în care se manifestă proprietățile corpusculare ale luminii.", "a": "Fenomenele de emisie și absorbție: efectul fotoelectric, efectul Compton.", "e": "Ambele se explică prin transferul de energie și impuls între fotoni și materie.", "o": ["Interferență, difracție și polarizare", "Reflexie, dublă refracție și absorbție selectivă prin dicroism", "tan θᴮ = n₂/n₁"], "ref": "Lucrări practice, p. 163"}, {"id": 187, "topic": 3, "q": "Identificați metodele de polarizare a luminii prezentate în lucrare.", "a": "Polarizare prin reflexie și refracție; prin dublă refracție (nicol); prin transmisie (polaroid).", "e": "Aceste metode selectează o orientare a câmpului electric.", "o": ["Efect fotoelectric și efect Compton", "Lumină fără o orientare transversală preferată a câmpului electric", "Interferență, difracție și polarizare"], "ref": "Lucrări practice, p. 164"}, {"id": 188, "topic": 3, "q": "Precizați proprietățile razei ordinare și ale razei extraordinare rezultate prin dublă refracție în cristalul de spat de Islanda.", "a": "Ambele raze sunt total polarizate, cu planele de vibrație perpendiculare; raza ordinară se supune legilor refracției, raza extraordinară nu se supune.", "e": "În nicol: ordinară – reflexie totală, extraordinară – trece nedeviată.", "o": ["În (a), axele paralele permit transmisia maximă. În (b), axele încrucișate duc la extincție ideală", "Dicroismul este absorbția inegală a două polarizări ortogonale", "Alcool polivinilic orientat, compuși ai iodului și suport de acetat butirat de celuloză"], "ref": "Lucrări practice, p. 164–165"}, {"id": 189, "topic": 3, "q": "Identificați substanțele birefringente menționate în text.", "a": "Calcitul CaCO₃ (spat de Islanda), wurtita ZnS, cuarțul SiO₂, turmalina și chiar gheața.", "e": "Aceste cristale anizotrope pot oferi indici diferiți pentru polarizări diferite.", "o": ["Sticlă optică izotropă și apă pură în repaus", "Balsam de Canada și o soluție omogenă de NaCl", "Aer omogen și sticlă izotropă, fără tensiuni mecanice"], "ref": "Lucrări practice, p. 165"}, {"id": 190, "topic": 3, "q": "Identificați caracteristicile dicroismului și ale materialelor polaroide.", "a": "Cristalul dicroic (ex. turmalina) absoarbe una din cele două componente polarizate mult mai puternic decât pe cealaltă; polaroidul transmite doar componentele paralele cu direcția preferențială și le absoarbe pe cele perpendiculare.", "e": "Ex.: herapatit; PVA + iod.", "o": ["În (a), axele paralele permit transmisia maximă. În (b), axele încrucișate duc la extincție ideală", "Spat de Islanda și cuarț", "Două părți de cristal de calcit unite prin balsam de Canada"], "ref": "Lucrări practice, p. 165–166"}, {"id": 191, "topic": 3, "q": "În imaginea alăturată, identificați efectele trecerii luminii prin cei doi polaroizi în pozițiile (a) și (b).", "a": "(a) Polarizori paraleli (ambii verticali) – lumina polarizată trece prin al doilea. (b) Încrucișați (vertical + orizontal) – intensitatea devine nulă.", "e": "Analizorul transmite I = I₀ cos²θ.", "o": ["Raza ordinară respectă legea refracției cu indice nₒ constant, raza extraordinară are indice efectiv dependent de direcție", "Dicroismul este absorbția inegală a două polarizări ortogonale", "Alcool polivinilic orientat, compuși ai iodului și suport de acetat butirat de celuloză"], "image": "../fig-191.png", "ref": "Lucrări practice, p. 166–167"}, {"id": 192, "topic": 3, "q": "Identificați substanțele dextrogire menționate în text.", "a": "Glucoza, lactoza, alanina, progesteronul.", "e": "Rotesc spre dreapta.", "o": ["Natura substanței, lungimea de undă, temperatura și mediul de măsurare", "Fructoza, serina și colesterolul, ca exemple din manual", "φ este direct proporțional cu C și l pentru [α] constant"], "ref": "Lucrări practice, p. 167"}, {"id": 193, "topic": 3, "q": "Identificați substanțele levogire menționate în text.", "a": "Fructoza, serina, colesterolul.", "e": "Rotesc spre stânga.", "o": ["φ este direct proporțional cu C și l pentru [α] constant", "Glucoza, lactoza, alanina și progesteronul, ca exemple din manual", "Natura substanței, lungimea de undă, temperatura și mediul de măsurare"], "ref": "Lucrări practice, p. 167"}, {"id": 194, "topic": 3, "q": "Precizați factorii de care depinde unghiul de rotire specifică [α] al unei substanțe optic active.", "a": "Natura substanței, temperatura și lungimea de undă a luminii (invers proporțional cu λ²).", "e": "Rotația specifică standard se raportează la o temperatură și o lungime de undă precizate.", "o": ["Glucoza, lactoza, alanina și progesteronul, ca exemple din manual", "φ este direct proporțional cu C și l pentru [α] constant", "Fructoza, serina și colesterolul, ca exemple din manual"], "ref": "Lucrări practice, p. 167"}, {"id": 195, "topic": 3, "q": "Precizați proporționalitățile valabile pentru unghiul de rotire φ în relația φ = [α]·C·l / 100.", "a": "φ este direct proporțional cu concentrația C și cu lungimea l a stratului (și cu [α]).", "e": "La temperatură și λ date.", "o": ["φ este proporțional cu C și invers proporțional cu l", "φ este proporțional cu l, dar independent de C", "φ este proporțional cu C² și cu 1/l"], "image": "../fig-195.png", "ref": "Lucrări practice, p. 167"}, {"id": 196, "topic": 3, "q": "Identificați aplicațiile luminii polarizate în medicina clinică și cercetarea biofizică.", "a": "Polarimetrie pentru soluții optic active și microscopie cu lumină polarizată pentru structuri birefringente", "e": "Microscopia polarizantă evidențiază structuri birefringente. Polarimetria măsoară rotația optică și poate fi folosită la analiza soluțiilor optic active.", "o": ["În (a) centrul este întunecat, în (b) iluminarea este uniformă, iar în (c) centrul este luminos", "Natura substanței, lungimea de undă, temperatura și mediul de măsurare", "Glucoza, lactoza, alanina și progesteronul, ca exemple din manual"], "ref": "Lucrări practice, p. 168"}, {"id": 197, "topic": 3, "q": "În imaginea alăturată, identificați componentele din schema optică a polarimetrului notate cu P, T și A.", "a": "P – polarizor; T – tub cu soluție; A – analizor.", "e": "P pregătește polarizarea, T o rotește, iar A permite măsurarea rotației.", "o": ["φ = [α]Cl/100 pentru l în dm și C în g/100 mL", "1 = lupă, 4 = scară și vernier, 7 = LED", "φ este direct proporțional cu C și l pentru [α] constant"], "image": "../fig-198.png", "ref": "Lucrări practice, p. 169"}, {"id": 198, "topic": 3, "q": "În imaginea alăturată, identificați componentele corespunzătoare cifrelor 1, 4 și 7 la polarimetrul P1000LED.", "a": "1 – lupă; 4 – scară și vernier; 7 – lumina LED.", "e": "Lupa și vernierul facilitează citirea. LED-ul iluminează sistemul.", "o": ["1 = ocular, 4 = tub, 7 = polarizor", "1 = LED, 4 = scară, 7 = ocular", "1 = lupă, 4 = polarizor, 7 = tub"], "image": "../fig-199.png", "ref": "Lucrări practice, p. 169"}, {"id": 199, "topic": 3, "q": "În imaginea alăturată, identificați descrierile corecte pentru stările câmpului vizual (a), (b) și (c).", "a": "(a) părțile laterale întunecate, mijlocul luminat (la încrucișare); (b) iluminare uniformă – poziția corectă de citire; (c) mijlocul întunecat, părțile laterale luminoase.", "e": "În imaginea din fișă, poziția de egală iluminare pentru citire este (b).", "o": ["a) centru luminos, b) uniform, c) centru întunecat", "a) uniform, b) centru întunecat, c) centru luminos", "a) centru întunecat, b) centru luminos, c) uniform"], "image": "../fig-200.png", "ref": "Lucrări practice, p. 170"}, {"id": 200, "topic": 3, "q": "Identificați afirmațiile adevărate referitoare la vectorul luminii E.", "a": "Este componenta electrică a undei; e numit vectorul luminii, caracteristica de bază; de el depinde acțiunea chimică și biologică (asupra ochiului); oscilează perpendicular pe H și pe direcția de propagare; planul oscilațiilor lui = plan de polarizare.", "e": "Într-o undă plană în vid E este perpendicular pe direcția de propagare și pe B.", "o": ["Ultravioletul la capătul violet, infraroșul la capătul roșu", "Prin reflexie la unghiul Brewster, birefringență cu separare sau absorbție dicroică", "Reflexie, dublă refracție și absorbție selectivă prin dicroism"], "ref": "Lucrări practice, p. 162–163"}, {"id": 201, "topic": 3, "q": "În imaginea alăturată, identificați domeniile de radiație aflate la extremitățile spectrului vizibil.", "a": "Ultravioletul (lângă violet, ~400 nm) și infraroșul (lângă roșu, ~700–760 nm).", "e": "Ultravioletul are lungimi de undă mai scurte decât vizibilul, iar infraroșul mai lungi.", "o": ["Infraroșu spre violet și ultraviolet spre roșu", "Raze X imediat la ambele extremități ale vizibilului", "Microunde spre violet și raze gamma spre roșu"], "image": "../fig-202.png", "ref": "Lucrări practice, p. 163"}, {"id": 202, "topic": 3, "q": "Precizați detaliile constructive ale nicolului.", "a": "Cristal de spat de Islanda tăiat pe diagonala scurtă, fețele lipite cu balsam de Canada (unghiuri 22° și 68°); raza ordinară e reflectată total, cea extraordinară trece.", "e": "Construcția transmite raza extraordinară și elimină raza ordinară prin reflexie totală.", "o": ["Alcool polivinilic orientat, compuși ai iodului și suport de acetat butirat de celuloză", "Raza ordinară se reflectă total la balsam, iar cea extraordinară este transmisă", "Dicroismul este absorbția inegală a două polarizări ortogonale"], "ref": "Lucrări practice, p. 164–165"}, {"id": 203, "topic": 3, "q": "Identificați componentele folosite la fabricarea peliculelor polaroid moderne.", "a": "Lanțuri moleculare lungi, aliniate și paralele, într-o peliculă flexibilă de plastic (ex. alcool polivinilic PVA întins și colorat cu cerneală cu iod, laminat pe acetat butirat de celuloză).", "e": "PVA întins și tratat cu iodură produce dicroism, iar suportul stabilizează pelicula.", "o": ["Raza ordinară se reflectă total la balsam, iar cea extraordinară este transmisă", "Două părți de cristal de calcit unite prin balsam de Canada", "În (a), axele paralele permit transmisia maximă. În (b), axele încrucișate duc la extincție ideală"], "ref": "Lucrări practice, p. 166"}, {"id": 204, "topic": 3, "q": "Identificați metodele de obținere a luminii polarizate din lumina nepolarizată.", "a": "Reflexie și refracție (Brewster), dublă refracție (nicol), transmisie prin polaroid (dicroism).", "e": "Fiecare metodă selectează componente după polarizare.", "o": ["Vizibilul este între UV și IR. Undele radio au λ mai mare, iar razele X și γ au λ mai mică", "a) orientări multiple, b) două direcții ortogonale ilustrate, c) o direcție fixă a vectorului E", "Ultravioletul la capătul violet, infraroșul la capătul roșu"], "ref": "Lucrări practice, p. 164"}, {"id": 205, "topic": 3, "q": "În imaginea alăturată, identificați afirmațiile corecte privind domeniile spectrului electromagnetic.", "a": "Undele EM au λ de la 10⁸ nm la 10⁻¹⁶ nm; razele γ au λ cea mai mică și frecvența cea mai mare, urmate de X, UV, vizibil, IR, microunde, unde radio; vizibilul (400–760 nm) e o porțiune mică între UV și IR.", "e": "În vid ν = c/λ, astfel că frecvența variază invers cu λ.", "o": ["a) orientări multiple, b) două direcții ortogonale ilustrate, c) o direcție fixă a vectorului E", "Prin reflexie la unghiul Brewster, birefringență cu separare sau absorbție dicroică", "Ultravioletul la capătul violet, infraroșul la capătul roșu"], "image": "../fig-206.png", "ref": "Lucrări practice, p. 162–163"}, {"id": 206, "topic": 3, "q": "În imaginea alăturată, identificați semnificațiile corecte ale schemelor a), b) și c) privind orientarea vectorului E.", "a": "a) lumină naturală (nepolarizată); b) și c) lumină plan (liniar) polarizată – oscilațiile au loc în plane paralele.", "e": "În (c), E oscilează pe o singură direcție. Pentru polarizare circulară, două componente ortogonale egale ar trebui să aibă un defazaj de ±π/2.", "o": ["Vizibilul este între UV și IR. Undele radio au λ mai mare, iar razele X și γ au λ mai mică", "Prin reflexie la unghiul Brewster, birefringență cu separare sau absorbție dicroică", "Ultravioletul la capătul violet, infraroșul la capătul roșu"], "image": "../fig-207.png", "ref": "Lucrări practice, p. 163"}, {"id": 207, "topic": 3, "q": "În imaginea alăturată, identificați afirmațiile care descriu corect separarea razelor în prisma Nicol.", "a": "Lumina nepolarizată se divide în două raze polarizate perpendicular; raza ordinară suferă reflexie totală pe stratul de balsam de Canada și e eliminată lateral; raza extraordinară trece practic nedeviată și iese polarizată.", "e": "Nicolul = polarizor.", "o": ["Alcool polivinilic orientat, compuși ai iodului și suport de acetat butirat de celuloză", "Două părți de cristal de calcit unite prin balsam de Canada", "În (a), axele paralele permit transmisia maximă. În (b), axele încrucișate duc la extincție ideală"], "image": "../fig-208.png", "ref": "Lucrări practice, p. 164–165 V. Absorbția luminii. Fotocolorimetria Lucrarea 23 – p. 192–198"}, {"id": 208, "topic": 4, "q": "Definiți fluxul de lumină.", "a": "Cantitatea de energie transportată de unda electromagnetică printr-o suprafață oarecare într-o unitate de timp.", "e": "În convenția energetică din acest capitol, unitatea este wattul. Fluxul luminos fotometric se exprimă în lumeni.", "o": ["Energia radiantă pe unitatea de timp și de suprafață perpendiculară pe fascicul", "Absorbția spectrală diferită a oxihemoglobinei și a hemoglobinei dezoxigenate", "Transferul energiei luminii către mediul străbătut"], "ref": "Lucrări practice, p. 192"}, {"id": 209, "topic": 4, "q": "Definiți intensitatea luminii.", "a": "Cantitatea de energie transportată de unda de lumină într-o unitate de timp printr-o unitate de suprafață perpendiculară pe direcția de propagare (densitatea fluxului de lumină).", "e": "Manualul numește această densitate de flux intensitatea luminii, măsurată aici în W/m². Intensitatea luminoasă fotometrică are o altă definiție și se exprimă în candele.", "o": ["Energia radiantă care traversează o suprafață în unitatea de timp, Φ = dE/dt", "Absorbția spectrală diferită a oxihemoglobinei și a hemoglobinei dezoxigenate", "Transferul energiei luminii către mediul străbătut"], "ref": "Lucrări practice, p. 192"}, {"id": 210, "topic": 4, "q": "Definiți fenomenul de absorbție a luminii.", "a": "Atenuarea intensității luminii la trecerea prin substanță ca urmare a transformării energiei luminoase în alte forme de energie (termică, chimică etc.).", "e": "Lumina provoacă oscilații forțate ale electronilor.", "o": ["Efect predominant termic în contextul manualului", "Energia radiantă care traversează o suprafață în unitatea de timp, Φ = dE/dt", "Energia radiantă pe unitatea de timp și de suprafață perpendiculară pe fascicul"], "ref": "Lucrări practice, p. 192"}, {"id": 211, "topic": 4, "q": "Ce efect produce absorbția radiației vizibile și infraroșii în piele?", "a": "Încălzirea pielii.", "e": "UV, în schimb, provoacă reacții fotochimice (bronzare).", "o": ["Transferul energiei luminii către mediul străbătut", "Energia radiantă care traversează o suprafață în unitatea de timp, Φ = dE/dt", "Energia radiantă pe unitatea de timp și de suprafață perpendiculară pe fascicul"], "ref": "Lucrări practice, p. 192"}, {"id": 212, "topic": 4, "q": "Care este expresia legii Bouguer–Lambert pentru un fascicul paralel de lumină monocromatică într- un mediu omogen?", "a": "Id = I₀·e^(–kλ·d).", "e": "Legea Bouguer–Lambert.", "o": ["I = I₀ exp(+kλd)", "I = I₀(1 − kλd) pentru orice d", "I = I₀ exp(−kλ/d)"], "ref": "Lucrări practice, p. 193"}, {"id": 213, "topic": 4, "q": "Precizați ce indică semnul „−” din relația legii Bouguer–Lambert I_d = I₀ exp(−kλd)", "a": "Că la trecerea prin substanță intensitatea luminii se micșorează.", "e": "Scădere exponențială.", "o": ["D = ln(I₀/I) = −ln τ în convenția naturală a fișei", "Fiecare strat absoarbe o fracție din fasciculul care ajunge la el", "Coeficient de atenuare prin absorbție pe unitatea de lungime, kλ = −ln(I/I₀)/d"], "ref": "Lucrări practice, p. 193"}, {"id": 214, "topic": 4, "q": "Identificați factorii de care depinde coeficientul monocromatic natural de absorbție al unei substanțe.", "a": "Lungimea de undă a luminii și natura substanței.", "e": "Pentru o soluție diluată, la λ fixă, kλ = χλC.", "o": ["Coeficient de atenuare prin absorbție pe unitatea de lungime, kλ = −ln(I/I₀)/d", "Arată atenuarea intensității pe măsură ce crește grosimea", "Fiecare strat absoarbe o fracție din fasciculul care ajunge la el"], "ref": "Lucrări practice, p. 193"}, {"id": 215, "topic": 4, "q": "Definiți coeficientul monocromatic natural de absorbție conform sensului său fizic.", "a": "Este numeric egal cu mărimea inversă a grosimii stratului în care intensitatea luminii se micșorează de e ori (kλ = 1/d).", "e": "Ex.: aer 10⁻³ m⁻¹, apă 0,4 m⁻¹.", "o": ["Coeficient egal cu grosimea necesară ca I să scadă la I₀/e", "Fracția I/I₀, care se măsoară fără unitate", "Coeficient definit prin kλ = ln(I/I₀)/d pentru o probă absorbantă"], "ref": "Lucrări practice, p. 193"}, {"id": 216, "topic": 4, "q": "Definiți coeficientul de transmisie optică al unei substanțe.", "a": "Raportul dintre intensitatea luminii trecute prin substanță și intensitatea incidentă: τ = Id/I₀.", "e": "Arată ce parte din flux trece; se exprimă în %.", "o": ["τ = I₀/I", "τ = (I₀ − I)/I₀", "τ = ln(I₀/I)"], "ref": "Lucrări practice, p. 194"}, {"id": 217, "topic": 4, "q": "Definiți extincția (densitatea optică) a unei substanțe.", "a": "Logaritmul natural al inversului coeficientului de transmisie: D = ln(1/τ).", "e": "Arată cât de mult absoarbe substanța lumina.", "o": ["D = ln τ", "D = 1 − τ", "D = I₀/I"], "ref": "Lucrări practice, p. 195"}, {"id": 218, "topic": 4, "q": "Precizați principiul fizic pe care se bazează metoda medicală numită oxihemometrie.", "a": "Variația spectrului de absorbție al sângelui în funcție de saturația lui cu oxigen.", "e": "Oxihemometria determină saturația cu O₂.", "o": ["Energia radiantă pe unitatea de timp și de suprafață perpendiculară pe fascicul", "Energia radiantă care traversează o suprafață în unitatea de timp, Φ = dE/dt", "Efect predominant termic în contextul manualului"], "ref": "Lucrări practice, p. 197"}, {"id": 219, "topic": 4, "q": "În figura alăturată, ce semnifică reducerea succesivă a numărului de săgeți la trecerea luminii prin cele două straturi?", "a": "Straturile de aceeași grosime absorb întotdeauna aceeași parte din intensitatea incidentă – intensitatea scade treptat (exponențial) cu grosimea.", "e": "După straturi succesive, transmisiile se înmulțesc. Straturi identice transmit aceeași fracție din intensitatea incidentă local.", "o": ["D = ln(I₀/I) = −ln τ în convenția naturală a fișei", "Coeficient de atenuare prin absorbție pe unitatea de lungime, kλ = −ln(I/I₀)/d", "Arată atenuarea intensității pe măsură ce crește grosimea"], "image": "../fig-220.png", "ref": "Lucrări practice, p. 193"}, {"id": 220, "topic": 4, "q": "Ce mărime fizică este reprezentată pe axa verticală a graficului alăturat?", "a": "Intensitatea luminii I (de la I₀ la Id).", "e": "Pe orizontală – distanța x (grosimea).", "o": ["Coeficientul de absorbție χλ", "Lungimea de undă λ", "Coordonata de propagare x"], "image": "../fig-221.png", "ref": "Lucrări practice, p. 193"}, {"id": 221, "topic": 4, "q": "Ce componentă se află între lentila L și cuva K în schema alăturată?", "a": "Filtrul optic F.", "e": "Ordinea: S – Fa – L – F – K – CF – G.", "o": ["Celula fotoelectrică", "Aparatul de citire G", "Sursa de lumină S"], "image": "../fig-222.png", "ref": "Lucrări practice, p. 195"}, {"id": 222, "topic": 4, "q": "Precizați rolul componentei CF din imaginea alăturată.", "a": "Celula fotovoltaică primește lumina trecută prin cuvă și o transformă în curent electric, măsurat de galvanometrul G (devierea ∝ fluxul de lumină).", "e": "Detectorul se află după cuvă, astfel încât semnalul să reflecte transmisia probei.", "o": ["Selectează lungimea de undă înaintea cuvei", "Focalizează lumina pe filtru", "Conține soluția colorată"], "image": "../fig-223.png", "ref": "Lucrări practice, p. 195"}, {"id": 223, "topic": 4, "q": "În graficul alăturat, cum variază coeficientul de absorbție χλ al pielii între 300 și 700 nm?", "a": "Foarte mare în UV (~300 nm), scade în vizibil și rămâne aproape constant până spre roșu, apoi continuă să scadă.", "e": "Graficul descrie o variație spectrală selectivă, nu o scădere liniară uniformă.", "o": ["Lumina are natură electromagnetică și este cuantificată în fotoni cu E = hν. Absorbția transferă energie materiei", "Fluxul energetic este energie pe timp. Intensitatea din acest capitol este fluxul pe suprafața normală la propagare.", "Absorbția spectrală diferită a oxihemoglobinei și a hemoglobinei dezoxigenate"], "image": "../fig-224.png", "ref": "Lucrări practice, p. 196–197"}, {"id": 224, "topic": 4, "q": "Care este efectul predominant al radiației ultraviolete absorbite în stratul superior al pielii?", "a": "Reacții fotochimice în stratul superior al pielii → bronzare (pigment cafeniu-închis).", "e": "Fotonii ultravioletului pot iniția reacții fotochimice în componentele pielii.", "o": ["Oxihemometria", "Efect predominant termic în contextul manualului", "Transferul energiei luminii către mediul străbătut"], "ref": "Lucrări practice, p. 192"}, {"id": 225, "topic": 4, "q": "Conform legii Bouguer–Lambert, cum variază intensitatea luminii transmise când crește grosimea unui strat omogen?", "a": "Scade exponențial.", "e": "Nu liniar!", "o": ["D = χλCd în convenția logaritmului natural", "Intensitatea luminii transmise I", "kλ = χλC pentru o soluție diluată"], "ref": "Lucrări practice, p. 193"}, {"id": 226, "topic": 4, "q": "Selectați formula intensității luminii absorbite.", "a": "Ia = I₀ – Id.", "e": "Nu poate fi măsurată direct.", "o": ["I_abs = I₀τ", "I_abs = I₀/τ", "I_abs = I₀ ln(1/τ)"], "ref": "Lucrări practice, p. 193"}, {"id": 227, "topic": 4, "q": "Care este expresia legii Bouguer–Lambert–Beer pentru o soluție colorată diluată?", "a": "Id = I₀·e^(–χλ·C·d).", "e": "Combinația Bouguer–Lambert + Beer.", "o": ["I = I₀ exp(+χλCd)", "I = I₀ exp(−χλC/d)", "I = I₀(1 − χλCd) pentru orice concentrație"], "ref": "Lucrări practice, p. 194"}, {"id": 228, "topic": 4, "q": "Care este expresia extincției D pentru o soluție colorată diluată?", "a": "D = χλ·C·d.", "e": "Aplicând −ln lui τ = exp(−χλCd) se obține relația liniară.", "o": ["D = 1/(χλCd)", "D = exp(−χλCd)", "D = χλCd ln 10"], "ref": "Lucrări practice, p. 195"}, {"id": 229, "topic": 4, "q": "În figura alăturată, identificați componenta marcată CF.", "a": "CF – celula fotovoltaică.", "e": "Între cuva K și galvanometrul G.", "o": ["Cuva K", "Filtrul F", "Lentila L"], "image": "../fig-230.png", "ref": "Lucrări practice, p. 195"}, {"id": 230, "topic": 4, "q": "Ce metodă permite determinarea saturației sângelui cu oxigen prin analiza spectrului său de absorbție?", "a": "Oxihemometria.", "e": "Analiza spectrului de absorbție al sângelui.", "o": ["Efect fotochimic predominant", "Încălzire, excitare, reacții fotochimice și, dacă energia permite, ionizare", "Absorbția variază cu λ, iar maximele și benzile caracterizează proba"], "ref": "Lucrări practice, p. 197"}, {"id": 231, "topic": 4, "q": "Identificați expresia legii lui Beer pentru o soluție colorată diluată.", "a": "kλ = χλ·C.", "e": "Coeficientul de absorbție e direct proporțional cu concentrația.", "o": ["kλ = χλ/C", "kλ = χλd", "kλ = C/χλ"], "ref": "Lucrări practice, p. 194"}, {"id": 232, "topic": 4, "q": "Ce mărimi pot fi măsurate direct cu colorimetrul fotoelectric?", "a": "Coeficientul de transmisie optică τ și extincția D.", "e": "Colorimetrul KF 77.", "o": ["Concentrația și masa molară fără etalonare", "Lungimea de undă și temperatura soluției", "Doar energia individuală a fotonilor transmiși"], "ref": "Lucrări practice, p. 195"}, {"id": 233, "topic": 4, "q": "Identificați afirmațiile corecte despre natura luminii, mărimile ei caracteristice și absorbția acesteia.", "a": "Lumina are natură electromagnetică și proprietăți dualiste (ondulatorii și corpusculare); se caracterizează prin flux și intensitate; la trecerea prin substanță se atenuează (absorbție) prin transformarea energiei în alte forme.", "e": "Modelul ondulatoriu descrie propagarea, iar modelul cuantic descrie schimbul de energie.", "o": ["Fluxul energetic este energie pe timp. Intensitatea din acest capitol este fluxul pe suprafața normală la propagare.", "Coeficientul scade la intrarea în vizibil, apoi se menține aproximativ constant înainte de a scădea din nou spre roșu", "Încălzire, excitare, reacții fotochimice și, dacă energia permite, ionizare"], "ref": "Lucrări practice, p. 192"}, {"id": 234, "topic": 4, "q": "Distingeți afirmațiile corecte privind fluxul de lumină și intensitatea luminii.", "a": "Fluxul = energie transportată printr-o suprafață în unitatea de timp; intensitatea = energie transportată în unitatea de timp prin unitatea de suprafață perpendiculară (densitatea fluxului).", "e": "Intensitatea se raportează la 1 m².", "o": ["Lumina are natură electromagnetică și este cuantificată în fotoni cu E = hν. Absorbția transferă energie materiei", "Coeficientul scade la intrarea în vizibil, apoi se menține aproximativ constant înainte de a scădea din nou spre roșu", "Încălzire, excitare, reacții fotochimice și, dacă energia permite, ionizare"], "ref": "Lucrări practice, p. 192"}, {"id": 235, "topic": 4, "q": "Selectați procesele și efectele pe care le poate provoca absorbția luminii în substanțe.", "a": "Încălzirea substanțelor, ionizarea, excitarea atomilor sau moleculelor, procese chimice (ex. bronzarea).", "e": "Efectul depinde de foton, absorbant și mecanismele de relaxare disponibile.", "o": ["Absorbția variază cu λ, iar maximele și benzile caracterizează proba", "Lumina are natură electromagnetică și este cuantificată în fotoni cu E = hν. Absorbția transferă energie materiei", "Fluxul energetic este energie pe timp. Intensitatea din acest capitol este fluxul pe suprafața normală la propagare."], "ref": "Lucrări practice, p. 192"}, {"id": 236, "topic": 4, "q": "Identificați semnificația simbolurilor din legea lui Bouguer–Lambert I_d = I₀ exp(−kλd)", "a": "I₀ – intensitatea incidentă; Id – intensitatea după stratul de grosime d; e ≈ 2,72 – baza logaritmului natural; kλ – coeficientul monocromatic natural de absorbție; d – grosimea stratului.", "e": "Produsul kλd trebuie să fie adimensional.", "o": ["Atenuare exponențială și fracție transmisă egală pentru grosimi egale din același mediu", "τ = I_d/I₀, fracție adimensională transmisă, cu valori între 0 și 1 pentru o probă pasivă", "La λ fixă, kλ = χλC și D este proporțională cu C la d constant"], "ref": "Lucrări practice, p. 193"}, {"id": 237, "topic": 4, "q": "Analizați particularitățile atenuării luminii la trecerea printr-un strat de substanță omogenă conform legii lui Bouguer–Lambert.", "a": "Intensitatea scade exponențial cu grosimea; straturi egale absorb aceeași fracțiune din lumina incidentă, indiferent de valoarea ei absolută; valabil pentru fascicul paralel monocromatic, mediu omogen.", "e": "Partea absolută absorbită de straturile succesive scade, fiindcă spre ele ajunge mai puțină lumină.", "o": ["Fiecare strat identic absoarbe aceeași cantitate absolută de energie", "Intensitatea scade liniar la orice grosime", "Transmitanța a două straturi identice este dublul transmitanței unuia"], "ref": "Lucrări practice, p. 193"}, {"id": 238, "topic": 4, "q": "Identificați afirmațiile corecte despre absorbția luminii monocromatice în soluții colorate diluate, potrivit legii lui Beer.", "a": "Absorbția respectă legea Bouguer–Lambert; kλ = χλ·C (direct proporțional cu concentrația); valabil pentru soluții colorate de concentrații mici, solvent transparent.", "e": "Legea lui Beer.", "o": ["D = −ln τ, deci scade când τ crește. Pentru τ = 1, D = 0", "Atenuare exponențială și fracție transmisă egală pentru grosimi egale din același mediu", "I este intensitatea transmisă, I₀ cea incidentă, kλ coeficientul natural și d grosimea"], "ref": "Lucrări practice, p. 194"}, {"id": 239, "topic": 4, "q": "Caracterizați coeficientul de transmisie optică τ pe baza sensului său fizic și a relației τ = Id / I0.", "a": "τ = Id/I₀ arată ce parte din fluxul de lumină trece prin substanță; τ ≤ 1 (≤ 100%); se exprimă în %.", "e": "Transparența optică.", "o": ["Atenuare exponențială și fracție transmisă egală pentru grosimi egale din același mediu", "I este intensitatea transmisă, I₀ cea incidentă, kλ coeficientul natural și d grosimea", "I₀ este incidentă, iar I_d este transmisă după grosimea d. Intensitatea intermediară se află între ele."], "ref": "Lucrări practice, p. 194"}, {"id": 240, "topic": 4, "q": "Identificați afirmațiile corecte despre extincția D și relația sa cu transmisia optică τ, pentru D = ln(1/τ).", "a": "D = ln(1/τ); dacă τ scade, D crește; D = χλCd – la d constant depinde doar de C și λ; caracterizează măsura absorbției.", "e": "La τ → 0, D crește fără limită în modelul matematic.", "o": ["D = ln τ și crește cu τ", "D = 1 − τ și variază liniar", "D = 1/τ și este egală cu 1 pentru τ = 1"], "ref": "Lucrări practice, p. 195"}, {"id": 241, "topic": 4, "q": "Selectați afirmațiile corecte despre funcționarea colorimetrului fotoelectric din figura alăturată.", "a": "Lumina de la sursa S trece prin fantă, lentilă, filtrul F și cuva K cu soluție, cade pe celula fotovoltaică CF; galvanometrul G deviază proporțional cu fluxul trecut prin soluție; se măsoară τ și D.", "e": "Comparația cu un blanc reduce contribuția solventului și a cuvei.", "o": ["Cuva selectează lungimea de undă, iar filtrul măsoară intensitatea transmisă", "Fotocelula se află înaintea probei și măsoară doar fasciculul incident", "Filtrul este înlocuit de etalonare, iar semnalul rezultă din rotația polarizării"], "image": "../fig-242.png", "ref": "Lucrări practice, p. 195"}, {"id": 242, "topic": 4, "q": "Identificați afirmațiile corecte despre absorbția selectivă și spectrele de absorbție.", "a": "Majoritatea substanțelor absorb selectiv – doar anumite λ, caracteristice; kλ și χλ depind de λ; spectrele de absorbție informează despre compoziția și structura substanțelor.", "e": "Poziția benzilor informează despre tranziții, iar intensitatea lor poate susține dozarea.", "o": ["Coeficientul de absorbție are aceeași valoare pentru toate lungimile de undă", "Benzile își schimbă automat poziția când se modifică lungimea cuvei", "Un maxim de transmisie coincide întotdeauna cu un maxim de absorbție la aceeași probă"], "ref": "Lucrări practice, p. 196"}, {"id": 243, "topic": 4, "q": "Selectați afirmațiile corecte privind aplicațiile metodelor fotometrice și fotocolorimetrice în medicină.", "a": "Oxihemometria (saturația sângelui cu O₂); colorimetria de concentrație (concentrația soluțiilor colorate); determinarea microelementelor din sânge și țesuturi cu exactitate 10⁻⁴–10⁻⁸ g/l.", "e": "Semnalul optic se compară cu un blanc și cu standarde, după metoda aleasă.", "o": ["Dozarea prin viteza de sedimentare și măsurarea presiunii arteriale", "Identificarea izotopilor prin numărarea impulsurilor Geiger", "Măsurarea saturației exclusiv din volumul probei și a concentrației din rotația polarizării"], "ref": "Lucrări practice, p. 197"}, {"id": 244, "topic": 4, "q": "În imaginea alăturată, identificați afirmațiile corecte privind mărimile și procesul de atenuare reprezentate schematic.", "a": "I₀ – lumina incidentă, Id – lumina ieșită după grosimea d; numărul de săgeți scade după fiecare strat egal → fiecare strat absoarbe aceeași fracțiune; atenuare exponențială.", "e": "Fiecare porțiune absorbantă reduce intensitatea locală. Pentru grosimi egale în același mediu, se transmite aceeași fracție în fiecare porțiune.", "o": ["I₀ este intensitatea incidentă, I cea transmisă, χλ coeficientul molar, C concentrația, d grosimea", "Fascicul monocromatic, mediu omogen și soluție suficient de diluată, cu împrăștiere neglijabilă", "τ = I_d/I₀, fracție adimensională transmisă, cu valori între 0 și 1 pentru o probă pasivă"], "image": "../fig-245.png", "ref": "Lucrări practice, p. 193"}, {"id": 245, "topic": 4, "q": "În graficul alăturat, identificați afirmațiile corecte despre scăderea intensității luminii cu distanța de propagare.", "a": "Intensitatea scade exponențial de la I₀ cu distanța x; Ix – intensitatea la distanța x; Id – intensitatea după grosimea d; curba nu atinge zero.", "e": "Panta este negativă, iar modulul ei scade pe măsură ce fasciculul slăbește.", "o": ["D = −ln τ, deci scade când τ crește. Pentru τ = 1, D = 0", "La λ fixă, kλ = χλC și D este proporțională cu C la d constant", "De concentrația C și de lungimea de undă prin χλ"], "image": "../fig-246.png", "ref": "Lucrări practice, p. 193"}, {"id": 246, "topic": 4, "q": "În imaginea alăturată, identificați afirmațiile corecte privind ordinea și rolul componentelor din schema colorimetrului fotoelectric.", "a": "Ordinea: S (sursă) → Fa (fantă) → L (lentilă) → F (filtru optic) → K (cuvă cu soluție) → CF (celulă fotovoltaică) → G (galvanometru).", "e": "Ordinea permite selectarea fasciculului înainte de probă și detectarea luminii după probă.", "o": ["Sursă → fotocelulă → cuvă → filtru → lentilă", "Sursă → cuvă → citire → filtru → fotocelulă", "Sursă → lentilă → celulă fotoelectrică → cuvă → filtru"], "image": "../fig-247.png", "ref": "Lucrări practice, p. 195"}, {"id": 247, "topic": 4, "q": "În figura alăturată, identificați afirmațiile corecte despre spectrul de absorbție al pielii.", "a": "Absorbția pielii e foarte mare în UV (razele UV sunt absorbite în straturile superioare); în vizibil scade și e aproape constantă până spre roșu, apoi scade.", "e": "Curba din manual este schematică. Ea arată caracterul selectiv al absorbției pielii.", "o": ["Absorbția atinge maximul în roșu și crește continuu de la 300 nm", "Absorbția este constantă de la ultraviolet la infraroșu", "Absorbția este minimă în UV și crește aproximativ liniar în vizibil"], "image": "../fig-248.png", "ref": "Lucrări practice, p. 196–197"}, {"id": 248, "topic": 4, "q": "Identificați consecințele legii Bouguer–Lambert pentru un strat omogen.", "a": "Intensitatea scade exponențial cu grosimea; straturi egale absorb aceeași parte din lumina incidentă; la d = 1/kλ intensitatea scade de e ori.", "e": "Două straturi identice cu τ fiecare au τ_total = τ² și D_total = 2D.", "o": ["Transmisiile se adună, extincțiile se înmulțesc", "Atât extincțiile, cât și transmisiile se adună", "Transmisiile se înmulțesc, iar extincțiile sunt identice cu ale unui singur strat"], "ref": "Lucrări practice, p. 193"}, {"id": 249, "topic": 4, "q": "Identificați semnificațiile simbolurilor din relația I_d = I₀ exp(−kλd)", "a": "Id – intensitatea transmisă; I₀ – intensitatea incidentă; e – baza logaritmului natural; kλ – coeficient monocromatic natural de absorbție; d – grosimea stratului.", "e": "Exponentul kλd este adimensional. În expresia pentru soluții diluate, kλ se poate scrie χλC.", "o": ["I_d este intensitatea incidentă, iar I₀ cea transmisă.", "kλ este coeficientul de transmisie adimensional, iar d concentrația soluției.", "I_d este intensitatea absorbită, iar kλ este grosimea stratului."], "ref": "Lucrări practice, p. 193"}, {"id": 250, "topic": 4, "q": "Identificați condițiile de aplicare a legii Bouguer–Lambert–Beer pentru soluții colorate diluate.", "a": "Lumină monocromatică, fascicul paralel, soluții colorate de concentrații mici, solvent absolut transparent pentru radiația dată; temperatură și λ date.", "e": "La concentrații mari și spectru larg, proporționalitatea D–C se poate abate de la modelul ideal.", "o": ["I₀ este intensitatea incidentă, I cea transmisă, χλ coeficientul molar, C concentrația, d grosimea", "Transmisiile se înmulțesc, extincțiile se adună, iar I scade exponențial cu grosimea", "χλ leagă kλ de concentrație prin kλ = χλC și depinde de λ și de specia absorbantă"], "ref": "Lucrări practice, p. 194"}, {"id": 251, "topic": 4, "q": "Identificați caracteristicile coeficientului molar monocromatic de absorbție χλ.", "a": "Coeficientul de absorbție pentru soluția cu concentrația molară unitară; la anumită temperatură și λ e constant pentru fiecare substanță – servește drept caracteristică a substanței; depinde de λ.", "e": "Cu C în mol/L și d în cm, χλ se poate exprima în L·mol⁻¹·cm⁻¹.", "o": ["Transmisiile se înmulțesc, extincțiile se adună, iar I scade exponențial cu grosimea", "Fascicul monocromatic, mediu omogen și soluție suficient de diluată, cu împrăștiere neglijabilă", "Fracție adimensională transmisă, τ = I/I₀, echivalentă cu exp(−D)"], "ref": "Lucrări practice, p. 194"}, {"id": 252, "topic": 4, "q": "Care afirmații despre coeficientul de transmisie optică sunt corecte?", "a": "τ = Id/I₀; arată ce parte din flux trece; se exprimă în %; τ = e^(–χλCd); scade când crește C sau d.", "e": "Transmisia procentuală este 100τ. Dacă D crește, τ scade.", "o": ["χλ leagă kλ de concentrație prin kλ = χλC și depinde de λ și de specia absorbantă", "kλ și D sunt proporționale cu C, iar I scade exponențial cu C la d fix", "De concentrația C și de lungimea de undă prin χλ"], "ref": "Lucrări practice, p. 194"}, {"id": 253, "topic": 4, "q": "Identificați afirmațiile corecte despre măsurarea luminii transmise cu un colorimetru fotoelectric.", "a": "Devierea acului galvanometrului e proporțională cu fluxul de lumină trecut prin soluție; se măsoară direct τ și D; se alege filtrul cu care τ e maxim; se construiesc graficele τ = f(C) și D = f(C) pentru concentrații necunoscute.", "e": "În domeniul liniar al detectorului, raportul semnalelor poate reprezenta transmitanța.", "o": ["Fotocelula măsoară energia radiației absorbite chiar înainte de probă", "Transmitanța se obține din diferența semnalelor fără raportare la referință", "Semnalul din probă crește când intensitatea transmisă scade, în domeniul liniar"], "ref": "Lucrări practice, p. 195–196"}, {"id": 254, "topic": 4, "q": "Identificați informațiile oferite de spectrele de absorbție.", "a": "Informații despre compoziția și structura substanțelor (inclusiv a mediilor biologice).", "e": "Identificarea folosește semnătura spectrală, iar măsurarea concentrației necesită condiții și etalonare adecvate.", "o": ["Numai grosimea stratului, fără informații despre compoziție", "Doar intensitatea totală, independent de lungimea de undă", "Sarcina specifică a particulelor din proba absorbantă"], "ref": "Lucrări practice, p. 196"}, {"id": 255, "topic": 4, "q": "Identificați utilizările fotocolorimetriei în studiul soluțiilor colorate și al mediilor biologice.", "a": "Determinarea concentrației soluțiilor colorate (colorimetria de concentrație), a microelementelor din sânge și țesuturi, saturația sângelui cu oxigen.", "e": "Un analit poate fi convertit chimic într-un produs colorat pentru măsurare.", "o": ["Dozarea se bazează pe masa cuvei măsurată înainte și după analiză", "În soluții se măsoară doar rotația optică, iar absorbția nu este utilizată", "Metoda identifică orice analit doar din intensitatea incidentă, fără măsurarea transmisiei"], "ref": "Lucrări practice, p. 197"}, {"id": 256, "topic": 4, "q": "Pentru aceeași substanță, la temperatură și grosime a stratului constante, de ce factori depinde extincția D?", "a": "De concentrația substanței în soluție și de lungimea de undă a luminii.", "e": "D = χλCd.", "o": ["D crește când τ scade și scade când τ crește", "D = χλCd = −ln τ, adimensională și liniară în C și d separat", "kλ și D sunt proporționale cu C, iar I scade exponențial cu C la d fix"], "ref": "Lucrări practice, p. 195"}, {"id": 257, "topic": 4, "q": "Precizați factorii de care depinde coeficientul monocromatic natural de absorbție k λ.", "a": "De lungimea de undă a luminii și de natura substanței (la soluții – și de concentrație: kλ = χλC).", "e": "La χλ fix, creșterea concentrației crește coeficientul kλ.", "o": ["La λ și temperatură fixate, χλ caracterizează absorbantul și este panta lui kλ în funcție de C", "I scade la creșterea oricăruia dintre χλ, C și d, dacă ceilalți factori pozitivi rămân constanți", "Fascicul monocromatic, mediu omogen și soluție suficient de diluată, cu împrăștiere neglijabilă"], "ref": "Lucrări practice, p. 193–194"}, {"id": 258, "topic": 4, "q": "Identificați concluziile stabilite de Beer privind absorbția luminii monocromatice în soluții colorate de concentrații mici.", "a": "1) Absorbția în soluții colorate respectă legea Bouguer–Lambert; 2) coeficientul de absorbție e direct proporțional cu concentrația: kλ = χλC.", "e": "Aceasta este diferența dintre relația liniară a extincției și cea exponențială a intensității transmise.", "o": ["I este proporțională cu C, iar D scade exponențial", "kλ este independent de C, iar D este proporțională cu 1/C", "I scade liniar cu C pentru orice C, iar D rămâne constantă"], "ref": "Lucrări practice, p. 194"}, {"id": 259, "topic": 4, "q": "Identificați afirmațiile care descriu coeficientul molar monocromatic de absorbție χ λ la temperatură și lungime de undă date.", "a": "Are valoare constantă pentru fiecare substanță (la T și λ date) și poate servi drept caracteristică a substanței; corespunde soluției de concentrație molară unitară.", "e": "În domeniul diluat ideal, χλ este constant pentru aceeași specie și aceleași condiții.", "o": ["Natura absorbantului, lungimea de undă și condițiile fizice. În soluții diluate, și concentrația", "I scade la creșterea oricăruia dintre χλ, C și d, dacă ceilalți factori pozitivi rămân constanți", "Fracția I/I₀ care traversează proba, fără unitate, exprimabilă și în procente"], "ref": "Lucrări practice, p. 194"}, {"id": 260, "topic": 4, "q": "Identificați afirmațiile despre sensul fizic și exprimarea transparenței optice τ.", "a": "τ arată ce parte din fluxul de lumină trece prin substanță; τ = Id/I₀; se exprimă în %.", "e": "75% transmisie corespunde lui τ = 0,75, nu valorii 75 în formule.", "o": ["Raportul I₀/I, adimensional și întotdeauna cel mult 1", "Fracția absorbită, 1 − I/I₀", "Logaritmul natural al raportului I₀/I"], "ref": "Lucrări practice, p. 194"}, {"id": 261, "topic": 4, "q": "Identificați proprietățile extincției (densității optice) D pentru o soluție colorată diluată.", "a": "D = ln(1/τ) = χλCd; la grosime constantă D depinde doar de C și λ; D crește direct proporțional cu concentrația.", "e": "ex. 7.", "o": ["D este proporțională cu τ și exprimată în W/m²", "D variază exponențial cu C și este independentă de d", "D se înjumătățește când τ se înjumătățește"], "ref": "Lucrări practice, p. 195"}, {"id": 262, "topic": 4, "q": "Pe baza relației alăturate, identificați modificarea intensității transmise la creșterea separată a fiecăruia dintre factorii χλ, C și d, când celelalte mărimi rămân constante. I_d = I₀ exp(−χλCd)", "a": "La creșterea separată a lui χλ, C sau d, intensitatea transmisă Id scade (exponențial).", "e": "Toți trei sunt în exponent cu semnul „–”.", "o": ["I crește, deoarece χλCd este pozitiv", "I scade numai la creșterea grosimii", "I rămâne constantă deoarece I₀ nu se schimbă"], "ref": "Lucrări practice, p. 194"}, {"id": 263, "topic": 4, "q": "Conform relației D = ln(1/τ), cum variază extincția când se modifică τ?", "a": "Când τ scade, D crește; când τ crește, D scade (D = 0 la τ = 1).", "e": "Relație logaritmică inversă.", "o": ["D se înjumătățește când τ se înjumătățește", "D scade când τ scade", "D este proporțională cu τ"], "ref": "Lucrări practice, p. 195 VI. Recapitulare din prelegeri (membrane, electrochimie, radiații, magnetism, nucleu) Prelegeri – cap. 8, 9, 11–17, 19"}, {"id": 264, "topic": 5, "q": "Definiți potențialul chimic al solvitului.", "a": "Energia potențială a solvitului, în funcție de concentrație: μK = μ₀ + RT·ln CM.", "e": "μ₀ – potențial standard (C = 1, 25°C).", "o": ["Energia Gibbs totală a soluției împărțită la cantitatea de solvent.", "Energia necesară evaporării unui mol de solvent la presiune fixă.", "Diferența de potențial electric dintre soluție și un electrod de referință."], "ref": "Prelegeri, p. 85"}, {"id": 265, "topic": 5, "q": "Identificați modelul actual al structurii membranei", "a": "Modelul în mozaic fluid lipo-proteic (Singer și Nicolson, 1972).", "e": "Bistratul lipidic este fluid, iar proteinele membranare formează un mozaic și se pot deplasa lateral în limitele impuse de interacțiunile lor.", "o": ["Modelul rigid, cu un strat lipidic între două foi proteice continue.", "Modelul unui monostrat proteic cu fosfolipide dispersate în citoplasmă.", "Modelul unei pelicule lipidice omogene din care lipsesc proteinele."], "ref": "Prelegeri, p. 91"}, {"id": 266, "topic": 5, "q": "Definiți oxidarea în sensul transferului de electroni.", "a": "Procesul în care un element pierde unul sau mai mulți electroni, oferindu-i altui element.", "e": "Ex.: Ca = Ca²⁺ + 2e⁻.", "o": ["Câștigarea electronilor și scăderea numărului de oxidare.", "Pierderea protonilor fără transfer de electroni.", "Câștigarea neutronilor fără modificarea învelișului electronic."], "ref": "Prelegeri, p. 101"}, {"id": 267, "topic": 5, "q": "Identificați originea potențialului de electrod al unui metal introdus în electrolit.", "a": "Oxidarea metalului: atomii cedează electroni și trec în soluție ca ioni pozitivi → apare diferența de potențial metal–soluție (relația lui Nernst).", "e": "Schimbul de sarcină formează un strat electric dublu. Potențialul unui electrod se măsoară în raport cu un electrod de referință.", "o": ["Difuzia electronilor prin tot volumul electrolitului până se neutralizează interfața.", "Încălzirea electrolitului prin efect Joule în absența curentului.", "Potențialul chimic al solventului exprimat direct în volți."], "ref": "Prelegeri, p. 102"}, {"id": 268, "topic": 5, "q": "Identificați electrodul la care are loc oxidarea în pila Zn–Cu descrisă.", "a": "Electrodul de zinc (anodul).", "e": "Zn = Zn²⁺ + 2e⁻; cuprul e catodul.", "o": ["La electrodul de cupru, care este anodul pilei.", "La catodul de zinc, prin captarea electronilor de către Zn²⁺.", "În puntea salină, prin cedarea electronilor de către anioni."], "ref": "Prelegeri, p. 103"}, {"id": 269, "topic": 5, "q": "Identificați electrodul de referință folosit la definirea potențialului standard.", "a": "Electrodul standard de hidrogen (potențial definit 0 V).", "e": "Platină platinată în soluție acidă cu H⁺ = 1 mol/dm³ + H₂ gazos.", "o": ["Electrodul de calomel, cu 0 V prin definiția scării standard.", "Electrodul Ag/AgCl, cu 0 V indiferent de activitatea clorurii.", "Electrodul de cupru, cu 0 V în toate soluțiile."], "ref": "Prelegeri, p. 104"}, {"id": 270, "topic": 6, "q": "Identificați efectul în care fotonul incident provoacă expulzarea unui electron din atom.", "a": "Efectul fotoelectric.", "e": "Fotonul dispare, cedând toată energia electronului: hν = Wi + Ec.", "o": ["Împrăștierea elastică Rayleigh.", "Fluorescența de rezonanță.", "Emisia termică de radiație."], "ref": "Prelegeri, p. 122–123"}, {"id": 271, "topic": 6, "q": "Identificați fenomenul însoțit de apariția unui foton difuzat cu energie modificată.", "a": "Efectul Compton.", "e": "Apare un foton difuzat hν′: Ec = hν – Wi – hν′.", "o": ["Efectul fotoelectric, cu absorbția completă a fotonului.", "Împrăștierea Rayleigh, fără schimbare de frecvență.", "Transmisia printr-un mediu optic omogen fără interacțiune."], "ref": "Prelegeri, p. 123"}, {"id": 272, "topic": 6, "q": "Identificați forma dependenței randamentului tubului X de tensiune, pentru Z constant, în relația R=kZV.", "a": "Dependență liniară (direct proporțională) – R crește proporțional cu V.", "e": "R = kZV; R ≈ 1–2%.", "o": ["Randamentul scade ca 1/V.", "Randamentul crește ca V².", "Randamentul rămâne același dacă Z este constant."], "ref": "Prelegeri, p. 132"}, {"id": 273, "topic": 6, "q": "Definiți corpul absolut negru.", "a": "Corpul al cărui coeficient de absorbție este egal cu 1 pentru radiațiile de orice lungime de undă.", "e": "Abstracție fizică.", "o": ["Un reflector ideal care întoarce integral radiația incidentă.", "Un corp care absoarbe numai în vizibil și transmite toate celelalte lungimi de undă.", "Un corp care nu emite radiație termică la nicio temperatură."], "ref": "Prelegeri, p. 140"}, {"id": 274, "topic": 6, "q": "Identificați domeniul spectral al emisiei maxime a pielii la circa 32°C.", "a": "Infraroșu (λmax ≈ 9,5 μm).", "e": "Din legea lui Wien la 32°C.", "o": ["Ultravioletul apropiat, în jur de 0,32 μm.", "Roșul vizibil, în jur de 0,65 μm.", "Microundele, în jur de 9,5 mm."], "ref": "Prelegeri, p. 142"}, {"id": 275, "topic": 6, "q": "Identificați efectul creșterii temperaturii asupra lungimii de undă a maximului de emisie, potrivit legii lui Wien.", "a": "λmax se deplasează spre lungimi de undă mai scurte (λmax = b/T).", "e": "Legea deplasării.", "o": ["Lungimea de undă crește proporțional cu temperatura.", "Lungimea de undă rămâne fixă, iar maximul depinde doar de suprafață.", "Lungimea de undă crește ca T⁴."], "ref": "Prelegeri, p. 141"}, {"id": 276, "topic": 6, "q": "Identificați efectul vascular al iradierii infraroșii.", "a": "Vasodilatație (crește debitul sanguin, se intensifică schimburile dintre celule).", "e": "Absorbția radiației infraroșii încălzește țesutul și poate mări fluxul sanguin superficial.", "o": ["Vasoconstricția locală ca efect obișnuit al încălzirii.", "Ocluzia completă a vaselor superficiale în orice condiții.", "Scăderea obligatorie a fluxului sanguin prin răcire."], "ref": "Prelegeri, p. 146"}, {"id": 277, "topic": 6, "q": "Definiți luminescența.", "a": "Radiația suplimentară a corpului în raport cu radiația termică la temperatura dată, care durează mult mai mult decât perioada undelor de lumină („radiație rece”).", "e": "Fluorescența și fosforescența sunt forme de luminescență. Lumina provine din revenirea sistemului spre stări de energie mai mică.", "o": ["Emisia termică a unui corp incandescent.", "Reflexia speculară a luminii la suprafața unei probe.", "Atenuarea luminii doar prin absorbție, fără reemisie."], "ref": "Prelegeri, p. 149"}, {"id": 278, "topic": 6, "q": "Identificați particularitatea fluorescenței de rezonanță.", "a": "Atomul revine în starea inițială radiind un foton identic cu cel incident: hν′ = hν.", "e": "Se observă în vapori și gaze monoatomice.", "o": ["Emisia are întotdeauna frecvență dublă față de excitație.", "Emisia este obligatoriu deplasată spre lungimi de undă mai mari.", "Emisia apare exclusiv după o întârziere lungă, ca în fosforescență."], "ref": "Prelegeri, p. 150"}, {"id": 279, "topic": 6, "q": "Identificați efectul termic laser asociat temperaturilor de peste 100°C în țesuturi.", "a": "Volatilizarea (vaporizarea) țesuturilor.", "e": "La 60–100°C – coagulare.", "o": ["Fotobiomodularea fără efecte termice.", "Coagularea proteinelor ca efect unic, fără vaporizare.", "Fluorescența de rezonanță a apei tisulare."], "ref": "Prelegeri, p. 162–163"}, {"id": 280, "topic": 7, "q": "Identificați relația dintre inducția magnetică B și intensitatea H într-un mediu omogen.", "a": "B = μ₀·μ·H.", "e": "μ₀ = 4π·10⁻⁷; μ – permeabilitate relativă.", "o": ["B = H/(μ₀μᵣ).", "B = μ₀H + μᵣ, indiferent de mediu.", "H = μ₀μᵣB."], "ref": "Prelegeri, p. 165"}, {"id": 281, "topic": 7, "q": "Identificați unitatea SI a fluxului magnetic.", "a": "Weberul (Wb); 1 Wb = 1 T·m².", "e": "Fluxul magnetic este integrala componentei normale a inducției B pe o suprafață. Unitatea este produsul dintre tesla și metrul pătrat.", "o": ["Tesla (T).", "Henry (H).", "Amper pe metru (A/m)."], "ref": "Prelegeri, p. 167"}, {"id": 282, "topic": 5, "q": "Identificați mărimile din expresia potențialului electrochimic al unui ion.", "a": "μ₀ (potențial standard), R (constanta gazelor), T (temperatura absolută), CM (concentrația molară), V (potențialul electric), n (valența ionului), F (numărul lui Faraday): μ = μ₀ + RT ln CM ± VnF.", "e": "Pentru un mol de ioni, μ̃ᵢ = μᵢ° + RT ln aᵢ + zᵢFψ. Activitatea contribuie la termenul chimic, iar semnul lui zᵢ la cel electric.", "o": ["Numai μᵢ° și temperatura, indiferent de sarcină și activitate.", "Potențialul chimic și produsul zᵢF/ψ.", "Numai zᵢFψ, chiar dacă activitatea ionilor diferă."], "ref": "Prelegeri, p. 85"}, {"id": 283, "topic": 5, "q": "Identificați caracteristicile transportului activ membranar.", "a": "Se face contra gradientului (potențialului) electrochimic, cu consum de energie metabolică, prin pompe (complexe enzimatice), ex. pompa Na⁺–K⁺; la omul în repaus consumă 30– 40% din energia metabolică.", "e": "Transportul activ primar poate folosi ATP direct. Transportul secundar folosește energia gradientului altui ion.", "o": ["Deplasarea spontană prin bistrat exclusiv în sensul gradientului.", "Difuzia printr-un canal deschis fără aport energetic.", "Osmoza pasivă a apei printr-o membrană semipermeabilă."], "ref": "Prelegeri, p. 97–98"}, {"id": 284, "topic": 6, "q": "Identificați proprietățile undelor electromagnetice.", "a": "Formate din câmp electric (E) și magnetic (H) oscilante în fază, perpendiculare între ele și pe direcția de propagare; se propagă în vid cu viteza c; transportă energia în porțiuni – fotoni (ε = hν); λ = c/ν.", "e": "Pentru o undă plană în vid, câmpurile E și B sunt reciproc perpendiculare și perpendiculare pe direcția propagării. În vid, c = λν.", "o": ["Sunt unde longitudinale care necesită un mediu material.", "În vid, câmpurile E și B oscilează paralel cu direcția de propagare.", "Toate frecvențele au aceeași lungime de undă în vid."], "ref": "Prelegeri, p. 119–120"}, {"id": 285, "topic": 6, "q": "Identificați care dintre următoarele fenomene fizice reprezintă fenomene de interacțiune a fotonilor cu materia.", "a": "Simpla excitare a atomului, efectul fotoelectric, efectul Compton, crearea de perechi (hν > 1,022 MeV).", "e": "Acestea implică transfer de energie sau de impuls de la foton către materie. Formarea perechii lângă un nucleu cere o energie de cel puțin aproximativ 1,022 MeV.", "o": ["Dezintegrarea alfa, dezintegrarea beta și osmoza.", "Inducția electromagnetică, difuzia ionilor și electroliza.", "Numai efectul fotoelectric, deoarece împrăștierea Compton ar lăsa energia fotonului neschimbată."], "ref": "Prelegeri, p. 122–123"}, {"id": 286, "topic": 6, "q": "Identificați componentele și procesele relevante pentru tubul de raze X.", "a": "Tubul Coolidge: catod cu filament încălzit (emite electroni), anod metalic, tensiune de accelerare de zeci de kV, curent anodic de câțiva mA; procese: radiație de frânare (spectru continuu) și radiație caracteristică (spectru de linii); restul energiei → căldură.", "e": "Frânarea produce un spectru continuu, iar tranzițiile între straturile electronice ale țintei dau liniile caracteristice. O mare parte din energia electronilor devine căldură.", "o": ["Anodul emite electroni termionic, iar impactul se produce pe filamentul catodic.", "Electronii din tub generează doar linii caracteristice, fără spectru continuu.", "Filtrul optic transformă lumina filamentului în raze X, independent de tensiune."], "ref": "Prelegeri, p. 128–132"}, {"id": 287, "topic": 6, "q": "Identificați factorii din expresia randamentului R=kZV al tubului X.", "a": "k – constantă caracteristică tubului; Z – numărul atomic al materialului anodului; V – tensiunea de accelerare.", "e": "R = Φ/P = kZV.", "o": ["Z este sarcina electronului, iar V volumul tubului.", "Z este numărul de neutroni, iar V viteza electronilor.", "R este rezistența catodului, iar k conductivitatea țintei."], "ref": "Prelegeri, p. 132"}, {"id": 288, "topic": 6, "q": "Identificați caracteristicile legii lui Kirchhoff pentru radiația termică.", "a": "La temperatură constantă, raportul dintre densitatea spectrală a radianței și coeficientul monocromatic de absorbție e același pentru toate corpurile și egal cu densitatea spectrală a corpului negru: rλ/αλ = ελ.", "e": "Stabilită de Kirchhoff în 1859.", "o": ["Corpurile care absorb mai mult emit mai puțin în aceleași condiții.", "Emisivitatea este complementul absorptivității.", "Emisivitatea și absorptivitatea pot fi comparate fără a preciza lungimea de undă sau starea de echilibru."], "ref": "Prelegeri, p. 141"}, {"id": 289, "topic": 7, "q": "Identificați mărimile fizice din relația B=μ0μH.", "a": "B – inducția magnetică; μ₀ – constanta magnetică (4π·10⁻⁷); μ – permeabilitatea magnetică relativă a mediului; H – intensitatea câmpului magnetic.", "e": "μ₀μ = permeabilitatea absolută.", "o": ["B este fluxul magnetic în Wb, iar H este inducția în T.", "μ este permeabilitatea vidului, iar μ₀ permeabilitatea relativă adimensională.", "B și H sunt ambele energii magnetice măsurate în J."], "ref": "Prelegeri, p. 165"}, {"id": 290, "topic": 7, "q": "Identificați mărimile care influențează forța Ampère F = B I ℓ sinα.", "a": "Inducția B, intensitatea curentului I, lungimea conductorului ℓ, unghiul α dintre B și conductor.", "e": "Maximă la α = 90°.", "o": ["B, I și ℓ, înmulțite cu cosinusul unghiului dintre conductor și câmp.", "Numai curentul și rezistența electrică a conductorului.", "B, sarcina electronului și viteza sa, fără nicio dependență de lungimea conductorului."], "ref": "Prelegeri, p. 166"}, {"id": 291, "topic": 7, "q": "Identificați caracteristicile forței Lorentz magnetice.", "a": "FL = qVB·sin α; acționează asupra sarcinilor în mișcare; e perpendiculară pe viteză (regula mâinii stângi); nu efectuează lucru, doar schimbă direcția mișcării (traiectorie curbă).", "e": "Într-un câmp pur magnetic, forța schimbă direcția mișcării și nu efectuează lucru mecanic. Sensul se inversează când semnul sarcinii se schimbă.", "o": ["Forța este paralelă cu viteza și modifică direct energia cinetică.", "Forța are valoarea maximă când viteza este paralelă cu inducția.", "Forța este qB și există chiar dacă particula stă pe loc."], "ref": "Prelegeri, p. 167–168"}, {"id": 292, "topic": 7, "q": "Identificați caracteristicile forțelor nucleare.", "a": "Acționează la distanțe foarte mici (~10⁻¹⁵ m); între toți nucleonii, indiferent de sarcină; mult mai intense decât forțele electrice (compensează respingerea protonilor).", "e": "Ele explică legarea protonilor și neutronilor în nucleu și au caracter de saturație. Efectul lor scade rapid dincolo de câțiva femtometri.", "o": ["Sunt forțe electrice care acționează doar între protoni și au rază nelimitată.", "Sunt forțe gravitaționale care cresc cu distanța dintre nucleoni.", "Sunt exclusiv repulsive pentru orice distanță între nucleoni."], "ref": "Prelegeri, p. 177"}, {"id": 293, "topic": 7, "q": "Identificați afirmațiile despre energia de legătură nucleară.", "a": "Corespunde defectului de masă: Wleg = Δm·c²; este lucrul necesar pentru a desface nucleul în nucleoni separați; stabilitatea se apreciază prin energia de legătură pe nucleon B = Wleg/A.", "e": "Defectul de masă este diferența dintre suma maselor nucleonilor liberi și masa nucleului legat. Energia medie de legătură pe nucleon se obține împărțind la numărul de masă A.", "o": ["Energia de ionizare a electronilor periferici, egală cu Δm/c².", "Energia necesară separării nucleului, egală cu masa totală a nucleului înmulțită cu c².", "Diferența dintre energiile cinetice ale protonilor și electronilor orbitali."], "ref": "Prelegeri, p. 177"}, {"id": 294, "topic": 7, "q": "Identificați caracteristicile acceleratorului liniar.", "a": "Particula e accelerată de multe ori trecând printr-o serie de tuburi cilindrice legate la un generator de radiofrecvență; în interiorul tuburilor câmpul e nul, accelerarea are loc în intervalele dintre tuburi (polaritate opusă); l = V/ν; pentru energii mari trebuie lungime mare.", "e": "În radioterapie, un accelerator liniar poate furniza un fascicul de electroni sau poate produce raze X prin impactul electronilor pe o țintă.", "o": ["Accelerează particule neutre pe o orbită circulară printr-un câmp magnetic static.", "Mărește energia electronilor exclusiv prin forța magnetică Lorentz.", "Separă radiația prin difracție, fără a accelera particule."], "ref": "Prelegeri, p. 200"}, {"id": 295, "topic": 5, "q": "Conform cercetărilor parametrilor electrici ai membranelor biologice de către Coul și Cheortis, membrana biologică a fost privită ca (vezi figura alăturată):", "a": "Un condensator electric: mediile conductoare = soluțiile electrolitice din interior și exterior, separate de dublul strat lipidic (dielectric, ε = 2).", "e": "R ≈ 10⁷ Ω/m², C = 0,5·10⁻² F/m², grosime d ≈ 3,6 nm.", "o": ["Un rezistor metalic omogen pe toată grosimea membranei.", "Un inductor, în care câmpul magnetic este stocat între foile lipidice.", "Două surse galvanice legate în serie, fără dielectric."], "image": "../fig-295.png", "ref": "Prelegeri, p. 88–89"}, {"id": 296, "topic": 5, "q": "Conform modelului în mozaic elaborat de către Singer și Nicolson (vezi figura alăturată), structura de bază a membranelor celulare este formată din:", "a": "Stratul dublu lipidic, „perturbat” de proteinele membranare integrale și periferice.", "e": "Modelul mozaicului fluid.", "o": ["Două straturi proteice continue separate de un singur strat lipidic.", "Un singur strat de fosfolipide cu cozile expuse ambelor medii apoase.", "Un bistrat de carbohidrați cu proteine numai în citoplasmă."], "image": "../fig-296.png", "ref": "Prelegeri, p. 91"}, {"id": 297, "topic": 5, "q": "Identificați tipul de transport al substanțelor prin membrana celulară, ilustrat în figura alăturată.", "a": "Difuzia facilitată (transport pasiv mediat de molecule transportoare – modelul modificării conformaționale).", "e": "Proteina recunoaște molecula și o trece în celulă după gradientul electrochimic, fără consum de energie.Fig. 8.14.", "o": ["Difuziune simplă direct prin regiunea hidrofobă a lipidelor.", "Transport activ primar, cu hidroliza ATP pentru fiecare trecere.", "Endocitoză, prin formarea unei vezicule."], "image": "../fig-297.png", "ref": "Prelegeri, p. 96"}];
